'use strict';
window.CONCEPT_CHOICE_DATA={"calculus-chapter-01-review-1-concept-check-1":[{"label":"a","selectionPrompt":"Which statement correctly defines a function, its domain, and its range?","answer":"A function assigns each input in its domain exactly one output; its range is the set of outputs actually attained.","distractors":["A function can assign several outputs to one input; its domain is the output set and its range is the input set.","A function must assign different outputs to different inputs; its range includes every real number.","A function is any relation between two sets; its domain contains only inputs with positive outputs."],"explanation":"The defining restriction is one output per allowed input. The domain lists allowed inputs and the range lists actual outputs.","hint":"Ask how many outputs each permitted input may have, then distinguish inputs from outputs."},{"label":"b","selectionPrompt":"What is the graph of a function f?","answer":"The set of all points (x, f(x)) for x in the domain of f.","distractors":["The set of points (f(x), x) for x in the domain, which is always the graph of f.","Only the points where f(x) = 0.","All points (x, y) with x and y independently chosen from the domain."],"explanation":"Each graph point pairs an allowed input with its assigned output.","hint":"An ordered pair on the graph must satisfy the function’s input-output rule."},{"label":"c","selectionPrompt":"How can you tell whether a given curve is the graph of a function of x?","answer":"Every vertical line intersects the curve at most once.","distractors":["Every horizontal line intersects the curve at most once.","Every vertical line intersects the curve exactly twice.","The curve must be continuous and contain the origin."],"explanation":"Two points above the same x would assign two outputs to one input, violating the function definition.","hint":"Use a line that keeps the input coordinate fixed."}],"calculus-chapter-01-review-3-concept-check-1":[{"label":"a","selectionPrompt":"Which option gives the definition, graph symmetry, and three examples of even functions?","answer":"f(−x) = f(x) on a domain symmetric about 0; the graph is symmetric about the y-axis. Examples: x², cos x, and |x|.","distractors":["f(−x) = −f(x); the graph is symmetric about the origin. Examples: x, x³, and sin x.","f(x) is positive everywhere; the graph is symmetric about the x-axis. Examples: eˣ, x² + 1, and 2ˣ.","f(−x) = f(x) only at x = 0; the graph is symmetric about y = x. Examples: x, eˣ, and ln x."],"explanation":"Changing x to −x leaves an even function’s output unchanged, producing y-axis symmetry.","hint":"Test each example by replacing x with −x and compare the outputs."},{"label":"b","selectionPrompt":"Which option gives the definition, graph symmetry, and three examples of odd functions?","answer":"f(−x) = −f(x) on a domain symmetric about 0; the graph is symmetric about the origin. Examples: x, x³, and sin x.","distractors":["f(−x) = f(x); the graph is symmetric about the y-axis. Examples: x², cos x, and |x|.","f(x) is negative everywhere; the graph is symmetric about the x-axis. Examples: −eˣ, −x² − 1, and −2ˣ.","f(−x) = f(x) + 1; the graph is symmetric about y = x. Examples: x + 1, eˣ, and ln x."],"explanation":"For an odd function, negating the input negates the output. This gives a 180° rotational symmetry about the origin.","hint":"Compare the value at −x with the negative of the value at x."}],"calculus-chapter-01-review-4-concept-check-1":[{"label":"","selectionPrompt":"What does it mean for f to be increasing on an interval?","answer":"For any x₁ < x₂ in the interval, f(x₁) < f(x₂).","distractors":["For any x₁ < x₂ in the interval, f(x₁) > f(x₂).","f(x) is positive at every point of the interval.","The slope of f’s graph must itself increase throughout the interval."],"explanation":"Increasing compares outputs at two ordered inputs. Positive values and increasing slopes are different properties.","hint":"Compare the heights of the graph as you move from a smaller input to a larger one."}],"calculus-chapter-01-review-5-concept-check-1":[{"label":"","selectionPrompt":"What is a mathematical model?","answer":"A mathematical description of a real phenomenon, used to analyze it and make predictions under stated assumptions.","distractors":["An exact copy of reality that has no assumptions or approximations.","A graph of measured data that cannot be expressed through equations or other mathematics.","A formula whose predictions do not need to be compared with real observations."],"explanation":"A model expresses selected features of a phenomenon mathematically; observations help assess its usefulness.","hint":"Think about the link among a real phenomenon, simplifying assumptions, and predictions."}],"calculus-chapter-01-review-9-concept-check-1":[{"label":"a","selectionPrompt":"If f has domain A and g has domain B, what is the domain of f + g?","answer":"A ∩ B: the inputs at which both functions are defined.","distractors":["A ∪ B: the inputs at which at least one function is defined.","A alone, whether or not g is defined there.","B with every zero of f removed."],"explanation":"Adding function values requires both values at the same input.","hint":"Can you add two outputs if one of them does not exist?"},{"label":"b","selectionPrompt":"If f has domain A and g has domain B, what is the domain of fg?","answer":"A ∩ B: the inputs at which both factors are defined.","distractors":["A ∪ B: the inputs at which at least one factor is defined.","Only inputs where both f and g are positive.","A ∩ B with all zeros of both functions removed."],"explanation":"Multiplication requires both outputs to be defined; zero factors are allowed.","hint":"Distinguish multiplication by zero from an undefined factor."},{"label":"c","selectionPrompt":"If f has domain A and g has domain B, what is the domain of f/g?","answer":"{x ∈ A ∩ B : g(x) ≠ 0}.","distractors":["A ∪ B, including inputs where g(x) = 0.","{x ∈ A ∩ B : f(x) ≠ 0}, with no restriction on g(x).","{x ∈ A : f(x) > 0}, regardless of g."],"explanation":"Both outputs must exist, and the denominator must be nonzero. A zero numerator is allowed.","hint":"Check both the existence of the outputs and the restriction imposed by division."}],"calculus-chapter-01-review-10-concept-check-1":[{"label":"","selectionPrompt":"How is f ∘ g defined, and what is its domain?","answer":"(f ∘ g)(x) = f(g(x)); x must be in the domain of g and g(x) must be in the domain of f.","distractors":["(f ∘ g)(x) = g(f(x)); x must only be in the domain of g.","(f ∘ g)(x) = f(x)g(x); its domain is always all real numbers.","(f ∘ g)(x) = f(x) + g(x); its domain is the union of the two domains."],"explanation":"Composition feeds g’s output into f. Both stages must be defined.","hint":"Follow the input through the inner function first, then the outer function."}],"calculus-chapter-01-review-12-concept-check-1":[{"label":"a","selectionPrompt":"What is a one-to-one function, and how does its graph reveal this?","answer":"Distinct inputs have distinct outputs; every horizontal line intersects the graph at most once.","distractors":["Each input has one output; every vertical line intersects the graph at most once, which already proves one-to-one.","All outputs are positive; the graph lies above the x-axis.","Every real number is an output; every horizontal line must intersect the graph infinitely often."],"explanation":"One-to-one adds a restriction on repeated outputs beyond the basic function requirement.","hint":"Look for two different inputs that could share the same output."},{"label":"b","selectionPrompt":"For a one-to-one function f, how is its inverse defined and how is its graph obtained?","answer":"f⁻¹(y) = x exactly when f(x) = y; reflect the graph of f across the line y = x.","distractors":["f⁻¹(x) = 1/f(x); reflect the graph across the x-axis.","f⁻¹(x) = −f(x); reflect the graph across the y-axis.","f⁻¹(x) = f(−x); translate the graph one unit left."],"explanation":"The inverse reverses input and output roles, exchanging the coordinates of every graph point.","hint":"An inverse undoes the function’s mapping rather than taking its reciprocal."}],"calculus-chapter-01-review-13-concept-check-1":[{"label":"a","selectionPrompt":"How is inverse sine defined, and what are its domain and range?","answer":"y = sin⁻¹(x) is the unique angle in [−π/2, π/2] with sin y = x; domain: [−1, 1]; range: [−π/2, π/2].","distractors":["sin⁻¹(x) means 1/sin x; its domain and range are both all real numbers.","y = sin⁻¹(x) is the unique angle in [0, π] with sin y = x; domain: [−1, 1]; range: [0, π].","sin⁻¹(x) is defined for every complex input and returns every angle differing by 2π at once."],"explanation":"The inverse uses a standard restricted interval on which sine is one-to-one; its domain is the range of that restricted function.","hint":"Think about which interval makes the original trigonometric function one-to-one."},{"label":"b","selectionPrompt":"How is inverse cosine defined, and what are its domain and range?","answer":"y = cos⁻¹(x) is the unique angle in [0, π] with cos y = x; domain: [−1, 1]; range: [0, π].","distractors":["cos⁻¹(x) means 1/cos x; its domain and range are both all real numbers.","y = cos⁻¹(x) is the unique angle in [−π/2, π/2] with cos y = x; domain: [−1, 1]; range: [−π/2, π/2].","cos⁻¹(x) is defined for every complex input and returns every angle differing by 2π at once."],"explanation":"The inverse uses a standard restricted interval on which cosine is one-to-one; its domain is the range of that restricted function.","hint":"Think about which interval makes the original trigonometric function one-to-one."},{"label":"c","selectionPrompt":"How is inverse tangent defined, and what are its domain and range?","answer":"y = tan⁻¹(x) is the unique angle in (−π/2, π/2) with tan y = x; domain: all real numbers; range: (−π/2, π/2).","distractors":["tan⁻¹(x) means 1/tan x; its domain and range are both all real numbers.","y = tan⁻¹(x) is the unique angle in [0, π] with tan y = x; domain: all real numbers; range: [0, π].","tan⁻¹(x) is defined for every complex input and returns every angle differing by 2π at once."],"explanation":"The inverse uses a standard restricted interval on which tangent is one-to-one; its domain is the range of that restricted function.","hint":"Think about which interval makes the original trigonometric function one-to-one."}],"calculus-chapter-02-review-4-concept-check-1":[{"label":"","selectionPrompt":"What does the Squeeze Theorem say?","answer":"If g(x) ≤ f(x) ≤ h(x) near a, except possibly at a, and both outer functions tend to L, then f(x) tends to L.","distractors":["If g(x) ≤ f(x) ≤ h(x), then f has a limit whenever either outer function has a limit.","If g and h tend to different limits, f must tend to the average of those limits.","If f(a) lies between g(a) and h(a), then the limit of f at a must equal f(a)."],"explanation":"Matching limits of the two bounds force all intermediate values toward that same limit.","hint":"The bounds must trap the function near the point, and their limiting values must agree."}],"calculus-chapter-02-review-7-concept-check-1":[{"label":"a","selectionPrompt":"What does it mean for f to be continuous at a?","answer":"f(a) is defined, limₓ→ₐ f(x) exists, and that limit equals f(a).","distractors":["f(a) is defined; no condition on nearby values is necessary.","limₓ→ₐ f(x) exists, even if f(a) is missing or has another value.","f has a finite derivative at every point near a, but f(a) need not exist."],"explanation":"Continuity requires the actual function value to match the nearby limiting value.","hint":"Check the value, the limit, and whether they agree."},{"label":"b","selectionPrompt":"What does continuity on (−∞, ∞) mean, and what does it imply about the graph?","answer":"f is continuous at every real input; its graph has no breaks, jumps, or holes, though it can have corners.","distractors":["f is differentiable at every real input; its graph cannot have corners.","f is defined at every real input; jumps and holes are allowed.","f is continuous only at 0; all other graph points may be discontinuous."],"explanation":"Continuity everywhere excludes discontinuities but does not guarantee differentiability.","hint":"Distinguish a break in the graph from a corner in an unbroken graph."}],"calculus-chapter-02-review-9-concept-check-1":[{"label":"","selectionPrompt":"What does the Intermediate Value Theorem say?","answer":"If f is continuous on [a, b], every value between f(a) and f(b) is attained at some point of [a, b].","distractors":["If f is differentiable on (a, b), it takes every real value on [a, b].","If f(a) and f(b) have the same sign, f must have a zero between them.","Every function attains every value between f(a) and f(b), without a continuity assumption."],"explanation":"A continuous function cannot skip intermediate output values between its endpoint outputs.","hint":"Imagine moving along an unbroken graph between its two endpoint heights."}],"calculus-chapter-02-review-13-concept-check-1":[{"label":"","selectionPrompt":"Which option defines f′(a) and gives two interpretations?","answer":"f′(a) = limₕ→₀ [f(a+h) − f(a)]/h, if finite; it is the tangent slope and the instantaneous rate of change.","distractors":["f′(a) = f(a)/a; it is the average rate from the origin and the height of the tangent.","f′(a) = limₕ→₀ [f(a+h) + f(a)]/h; it is the area under the curve and its total change.","f′(a) = f(a+h) − f(a) for any nonzero h; it is the tangent intercept and total distance."],"explanation":"The derivative is the limiting secant slope as the input increment tends to zero.","hint":"Begin with change in output divided by change in input, then shrink the increment."}],"calculus-chapter-02-review-14-concept-check-1":[{"label":"","selectionPrompt":"What is the second derivative, and what does it mean for a particle’s position function?","answer":"f″ is the derivative of f′; for position f(t), f″(t) is acceleration.","distractors":["f″ is f multiplied by itself; for position it is speed squared.","f″ is an antiderivative of f′; for position it is displacement.","f″ is always the square of f′; for position it is distance traveled."],"explanation":"Position differentiates to velocity, and velocity differentiates to acceleration.","hint":"Apply the derivative operation a second time and follow the units."}],"calculus-chapter-02-review-15-concept-check-1":[{"label":"a","selectionPrompt":"What does it mean for f to be differentiable at a?","answer":"The derivative f′(a) exists as a finite real limit.","distractors":["f(a) exists, even if the difference quotient has no limit.","f is continuous at a, even if its graph has a corner there.","The difference quotient tends to positive or negative infinity."],"explanation":"A finite, well-defined limiting difference quotient is required for differentiability.","hint":"Differentiability asks whether a single finite tangent slope exists."},{"label":"b","selectionPrompt":"What is the relationship between differentiability and continuity?","answer":"Differentiability at a implies continuity at a; continuity at a need not imply differentiability there.","distractors":["Continuity at a implies differentiability at a; the reverse implication fails.","The two properties are equivalent at every point.","A function cannot be both continuous and differentiable at the same point."],"explanation":"A finite derivative forces the output change to tend to zero; continuous graphs can still have corners or cusps.","hint":"Use |x| at 0 to test whether continuity is enough for differentiability."}],"calculus-chapter-03-review-3-concept-check-1":[{"label":"a","selectionPrompt":"How is the number e defined in terms of an exponential derivative?","answer":"e is the positive base for which limₕ→₀ (eʰ − 1)/h = 1, so the slope of y = eˣ at x = 0 is 1.","distractors":["e is the base for which the slope of y = eˣ at x = 0 is 0.","e is the base for which e⁰ = 0.","e is the base for which the derivative of eˣ is the constant 1 at every x."],"explanation":"The natural base is selected so the exponential’s tangent slope at x = 0 is 1; this yields its self-derivative property.","hint":"Consider the slope at x = 0, not the value of the exponential there."},{"label":"c","selectionPrompt":"Why is the natural exponential eˣ especially useful in calculus?","answer":"Its derivative equals itself: d(eˣ)/dx = eˣ; other bases contribute a factor ln b.","distractors":["Its derivative is 1 at every x, unlike other exponential functions.","It is the only exponential function defined for negative inputs.","It is a polynomial, so repeated differentiation eventually gives zero."],"explanation":"The natural base eliminates the extra logarithmic factor in the exponential derivative.","hint":"Compare the derivative of bˣ with the special choice b = e."}],"calculus-chapter-03-review-4-concept-check-1":[{"label":"a","selectionPrompt":"How does implicit differentiation work?","answer":"Differentiate both sides with respect to x, treat y as a function of x using the chain rule, then solve for y′.","distractors":["Treat y as a constant when differentiating every term, then set y′ = 0.","Swap x and y in the equation and take reciprocals of both sides.","Integrate both sides with respect to y, then divide by x."],"explanation":"Terms involving y acquire factors of y′ because y depends on x.","hint":"The chain rule still applies when y is not isolated."},{"label":"b","selectionPrompt":"How does logarithmic differentiation work?","answer":"On an interval where y ≠ 0, take ln|y|, use logarithm laws, differentiate implicitly, and solve y′/y for y′.","distractors":["Replace every product by a sum without first taking logarithms, then differentiate.","Take ln y even when y is negative, and use y′ = d(ln y)/dx directly.","Differentiate ln|y| and conclude its derivative equals y′ without multiplying by y."],"explanation":"The chain rule gives d(ln|y|)/dx = y′/y; logarithm laws simplify products, quotients, and powers.","hint":"Logarithms simplify multiplicative structure, but the derivative of ln|y| has a denominator."}],"calculus-chapter-03-review-6-concept-check-1":[{"label":"b","selectionPrompt":"When is natural exponential growth an appropriate population model?","answer":"When the relative growth rate is approximately constant and limiting resources or crowding are negligible.","distractors":["When a fixed number of individuals is added per unit time regardless of population size.","When the population is close to a finite carrying capacity and growth must stop there.","When the growth rate is independent of both time and population and is exactly zero."],"explanation":"Exponential growth assumes dP/dt = kP, so the per-capita rate k remains constant.","hint":"Distinguish a constant per-capita rate from a constant total rate."}],"calculus-chapter-04-review-2-concept-check-1":[{"label":"a","selectionPrompt":"What does the Extreme Value Theorem guarantee?","answer":"A function continuous on a closed, bounded interval [a, b] attains both an absolute maximum and an absolute minimum there.","distractors":["Every function on an open interval attains a maximum and minimum.","A continuous function on any unbounded interval attains both extrema.","A differentiable function has an absolute maximum at every critical number."],"explanation":"Continuity and a closed, bounded interval together guarantee attainment of extrema.","hint":"Check both the regularity of the function and the type of interval."},{"label":"b","selectionPrompt":"How does the Closed Interval Method find absolute extrema?","answer":"Evaluate f at all critical numbers in (a, b) and at both endpoints; compare the resulting values.","distractors":["Evaluate f only where f′ = 0 and ignore the endpoints.","Compare the signs of f″ at the endpoints without evaluating f.","Choose the largest input as the maximum and the smallest input as the minimum."],"explanation":"Interior extrema occur at critical numbers; boundary extrema can occur at the endpoints.","hint":"The best value might lie inside the interval or on its boundary."}],"calculus-chapter-04-review-3-concept-check-1":[{"label":"a","selectionPrompt":"What does Fermat’s Theorem say?","answer":"If f has a local extremum at an interior point c and f′(c) exists, then f′(c) = 0.","distractors":["If f′(c) = 0, f must have a local maximum at c.","Every local extremum has a derivative, including corners.","If f has a local extremum at c, then f(c) = 0."],"explanation":"The theorem is a necessary condition at a differentiable interior extremum, not a sufficient test.","hint":"Keep the differentiability condition and the direction of the implication."},{"label":"b","selectionPrompt":"What is a critical number of f?","answer":"A number c in the domain of f at which f′(c) = 0 or f′(c) does not exist.","distractors":["Any c outside the domain at which f is undefined.","Only a number c at which f(c) = 0.","Only a number c where f′ changes from positive to negative."],"explanation":"Critical numbers include horizontal tangents and nondifferentiable points, but must belong to the function’s domain.","hint":"First require that the function exists, then examine its derivative."}],"calculus-chapter-04-review-5-concept-check-1":[{"label":"a","selectionPrompt":"What does the Increasing/Decreasing Test say?","answer":"On an interval, f′ > 0 implies f is increasing, and f′ < 0 implies f is decreasing.","distractors":["f > 0 implies increasing, and f < 0 implies decreasing.","f″ > 0 implies increasing, and f″ < 0 implies decreasing.","f′ > 0 implies decreasing, and f′ < 0 implies increasing."],"explanation":"The sign of the first derivative gives the direction of change in function values.","hint":"Use the slope’s sign rather than the graph’s height or bending."},{"label":"b","selectionPrompt":"What does concave upward on an interval mean?","answer":"The graph lies above its tangent lines throughout the interval, wherever those tangents exist.","distractors":["The function is positive throughout the interval.","The function is increasing throughout the interval.","The graph lies below its tangent lines throughout the interval."],"explanation":"Concavity describes bending relative to tangent lines; it does not require positive or increasing values.","hint":"Compare the curve with its tangent lines, not with the x-axis."},{"label":"c","selectionPrompt":"What does the Concavity Test say?","answer":"f″ > 0 on an interval implies concave upward; f″ < 0 implies concave downward.","distractors":["f′ > 0 implies concave upward; f′ < 0 implies concave downward.","f > 0 implies concave upward; f < 0 implies concave downward.","f″ > 0 implies concave downward; f″ < 0 implies concave upward."],"explanation":"The second derivative measures change in slope, which determines the direction of bending.","hint":"Which derivative tells you whether slopes are rising or falling?"},{"label":"d","selectionPrompt":"What is an inflection point, and how do you find it?","answer":"A point on a continuous graph where concavity changes; test candidates where f″ is zero or undefined for an actual sign change.","distractors":["Any point where f″ = 0, even if concavity stays the same.","Any point where f′ = 0, regardless of concavity.","Any input outside the domain where f″ does not exist."],"explanation":"Candidates alone are not enough: the graph must exist continuously at the point and change concavity.","hint":"Test the bending on both sides of a candidate."}],"calculus-chapter-04-review-11-concept-check-1":[{"label":"a","selectionPrompt":"What is an antiderivative F of f on an interval?","answer":"A function F whose derivative satisfies F′(x) = f(x) throughout the interval.","distractors":["A function F that satisfies F(x) = f′(x) throughout the interval.","A function F that satisfies F(x)f(x) = 1 throughout the interval.","A function F whose derivative is zero throughout the interval."],"explanation":"An antiderivative reverses differentiation by producing f as its derivative.","hint":"Check what happens when you differentiate the proposed F."},{"label":"b","selectionPrompt":"How are two antiderivatives F₁ and F₂ of the same f related on an interval?","answer":"F₁(x) − F₂(x) is a constant throughout the interval.","distractors":["F₁(x) = F₂(x) necessarily, with no constant difference allowed.","F₁(x)/F₂(x) is always 2 throughout the interval.","F₁(x) − F₂(x) can be any nonconstant function."],"explanation":"The derivative of their difference is zero on the interval, so the difference is constant.","hint":"Differentiate the difference of the two antiderivatives."}],"calculus-chapter-05-review-2-concept-check-1":[{"label":"a","selectionPrompt":"How is the definite integral of a continuous f from a to b defined?","answer":"As the limit of Riemann sums Σ f(xᵢ*) Δxᵢ as the partition mesh tends to 0.","distractors":["As one rectangle of height f(a) and width b − a, for every continuous f.","As the maximum value of f on [a, b] multiplied by b − a.","As the sum of all function values without any interval widths."],"explanation":"Refining partitions turns weighted rectangle sums into a unique limit for a continuous function.","hint":"Both the sampled heights and the small interval widths are needed."},{"label":"b","selectionPrompt":"What is the geometric meaning of ∫ₐᵇ f(x) dx when a < b and f ≥ 0?","answer":"The area between the graph and the x-axis over [a, b].","distractors":["The length of the graph over [a, b].","The slope of the graph at the midpoint.","The area above the graph extending infinitely upward."],"explanation":"For a nonnegative function, the signed area is ordinary area under the graph.","hint":"Think about the rectangles used to build the integral."}],"calculus-chapter-05-review-5-concept-check-1":[{"label":"a","selectionPrompt":"What does the Net Change Theorem say?","answer":"The integral of a rate of change over a time interval equals the net change in the quantity: ∫ₐᵇ F′(t) dt = F(b) − F(a).","distractors":["The integral of a rate always equals the total accumulated magnitude of change.","The integral of a rate equals the final quantity F(b), regardless of its initial value.","The derivative of a rate equals the net change over an interval."],"explanation":"Positive and negative rates contribute with their signs, so the result is final minus initial.","hint":"Keep net change distinct from total travel or total variation."}],"calculus-chapter-05-review-6-concept-check-1":[{"label":"a","selectionPrompt":"What does the velocity integral from 60 to 120 seconds represent?","answer":"The particle’s displacement from t = 60 s to t = 120 s, in feet.","distractors":["The total distance traveled, even if the particle reverses direction.","The particle’s acceleration at t = 120 s, in feet per second squared.","The particle’s speed at t = 60 s, in feet per second."],"explanation":"Integrating signed velocity gives net position change. A reversal can cancel earlier displacement.","hint":"Velocity has a sign that encodes direction."},{"label":"b","selectionPrompt":"What does ∫₆₀¹²⁰ |v(t)| dt represent?","answer":"The total distance traveled during that interval, in feet.","distractors":["The signed displacement, which may be negative.","The difference between final and initial speeds, in feet per second.","The average acceleration over that interval."],"explanation":"Absolute velocity is speed, and integrating speed accumulates travel without cancellation.","hint":"Ask what removing the velocity’s sign changes."},{"label":"c","selectionPrompt":"What does ∫₆₀¹²⁰ a(t) dt represent?","answer":"The change in velocity v(120) − v(60), in feet per second.","distractors":["The displacement from t = 60 to t = 120, in feet.","The total distance traveled over the interval, in feet.","The final acceleration a(120), in feet per second squared."],"explanation":"Acceleration is the rate of velocity change, so its integral is net velocity change.","hint":"Integrating a rate gives the change in the quantity whose rate it is."}],"calculus-chapter-05-review-7-concept-check-1":[{"label":"a","selectionPrompt":"What does the indefinite integral ∫ f(x) dx mean?","answer":"The family F(x) + C of all antiderivatives of f on an interval, where F′ = f.","distractors":["A single number measuring area on an unspecified interval.","The derivative f′(x) with an arbitrary constant added.","A unique antiderivative whose constant must always be zero."],"explanation":"An indefinite integral names a family of functions, since constants disappear under differentiation.","hint":"Consider whether the integral has bounds and what differentiation would undo."},{"label":"b","selectionPrompt":"How are definite and indefinite integrals connected for continuous f?","answer":"Choose an antiderivative F from ∫ f(x) dx; then ∫ₐᵇ f(x) dx = F(b) − F(a).","distractors":["Choose an antiderivative F; then ∫ₐᵇ f(x) dx = F(a) − F(b) for a < b.","The definite integral equals F(b) + F(a) + 2C.","The definite integral and indefinite integral are unrelated."],"explanation":"The Fundamental Theorem evaluates the definite integral using endpoint values of any antiderivative; the constant cancels.","hint":"Compare endpoint values and track what happens to the arbitrary constant."}],"calculus-chapter-05-review-8-concept-check-1":[{"label":"","selectionPrompt":"What precisely links differentiation and integration as inverse processes?","answer":"For continuous f, d/dx[∫ₐˣ f(t) dt] = f(x); for continuously differentiable F, ∫ₐᵇ F′(x) dx = F(b) − F(a).","distractors":["Differentiating every definite integral gives f(x), even when both endpoints are fixed constants.","Integrating any derivative gives exactly the original function with no possible constant difference.","Differentiation and integration commute without regularity conditions and both always return numbers."],"explanation":"The two parts of the Fundamental Theorem describe differentiating accumulation and integrating rates, with the necessary endpoint or constant adjustment.","hint":"Distinguish a variable upper bound from two fixed bounds."}],"calculus-chapter-06-review-2-concept-check-1":[{"label":"","selectionPrompt":"What does the area between Sue’s and Kathy’s velocity curves during the first minute represent?","answer":"The difference between the distances they have run in that minute; if they start together, Sue’s lead at one minute.","distractors":["The sum of their distances during the full 1500-meter race.","The difference in their accelerations exactly at one minute.","The time needed for Sue to finish the entire race."],"explanation":"The integral of the velocity difference is the difference in distances over the same interval.","hint":"Integrating velocity over time produces a distance change."}],"calculus-chapter-06-review-4-concept-check-1":[{"label":"c","selectionPrompt":"Why might cylindrical shells be preferable to slicing for a solid of revolution?","answer":"Shells may avoid solving for an inverse function or splitting the region, giving a simpler integral.","distractors":["Shells always give an exact volume while washers give only approximations.","Shells can be used only when the rotation axis intersects the region.","Shells ignore the distance from each strip to the rotation axis."],"explanation":"Both methods can be exact; the choice depends on which strip orientation produces simpler geometry and bounds.","hint":"Compare the algebra needed when strips are parallel versus perpendicular to the axis."}],"calculus-chapter-06-review-5-concept-check-1":[{"label":"","selectionPrompt":"What does ∫₀⁶ f(x) dx represent when f(x) is the pushing force in newtons along the motion?","answer":"The work done over the 6-meter displacement, measured in joules (newton-meters).","distractors":["The change in force, measured in newtons.","The average speed of the book, measured in meters per second.","The impulse on the book, measured in newton-seconds."],"explanation":"Force integrated over displacement gives work; the unit is N·m = J.","hint":"Check the differential’s unit: distance rather than time."}],"calculus-chapter-06-review-6-concept-check-1":[{"label":"a","selectionPrompt":"What is the average value of an integrable f on [a, b], where a < b?","answer":"fₐᵥₑ = (1/(b − a)) ∫ₐᵇ f(x) dx.","distractors":["fₐᵥₑ = f(a) + f(b), without dividing by anything.","fₐᵥₑ = (b − a) ∫ₐᵇ f(x) dx.","fₐᵥₑ = f′((a + b)/2) for every integrable f."],"explanation":"The total signed accumulation is divided by the interval length to obtain a mean height.","hint":"An average must account for the interval’s length."},{"label":"b","selectionPrompt":"What does the Mean Value Theorem for Integrals say and mean geometrically?","answer":"If f is continuous on [a, b] with a < b, some c ∈ [a, b] satisfies ∫ₐᵇ f = f(c)(b − a); a rectangle of height f(c) has the same signed area.","distractors":["Every integrable function has f((a + b)/2) equal to its average value.","For every continuous f, ∫ₐᵇ f = f(a)(b − a).","Some c satisfies f′(c) = ∫ₐᵇ f, so the tangent length equals the area."],"explanation":"Continuity ensures the average height is actually attained somewhere on the interval.","hint":"The matching rectangle’s height is an attained function value, not necessarily its midpoint value."}],"calculus-chapter-07-review-6-concept-check-1":[{"label":"a","selectionPrompt":"How is ∫ₐ^∞ f(x) dx defined as an improper integral?","answer":"limₜ→∞ ∫ₐᵗ f(x) dx; it converges if this limit is finite.","distractors":["∫ₐᵇ f(x) dx for any fixed b > a, with no limit.","limₜ→∞ f(t), with no integration.","limₜ→∞ ∫ₜᵃ f(x) dx, which uses the opposite orientation."],"explanation":"The unbounded upper endpoint is replaced by a finite endpoint and then taken to infinity.","hint":"Replace the infinite bound first; convergence requires a finite limiting integral."},{"label":"b","selectionPrompt":"How is ∫₋∞ᵇ f(x) dx defined?","answer":"limₜ→−∞ ∫ₜᵇ f(x) dx; it converges if this limit is finite.","distractors":["limₜ→∞ ∫ₜᵇ f(x) dx.","limₜ→−∞ of the integral from b down to t, reversing the required integration direction.","The single function value f(b)."],"explanation":"The lower endpoint tends to negative infinity while the upper endpoint stays fixed.","hint":"Preserve the direction from the lower bound to the upper bound."},{"label":"c","selectionPrompt":"How is ∫₋∞^∞ f(x) dx defined?","answer":"Split at any finite c and require both ∫₋∞ᶜ f and ∫ᶜ∞ f to converge; then add their values.","distractors":["Only take limₜ→∞ ∫₋ₜᵗ f; cancellation always establishes convergence.","Require convergence on the positive side only, ignoring the negative side.","Take limₓ→∞ f(x) and multiply it by an infinite width."],"explanation":"The two tails must converge separately. A symmetric principal value alone is not ordinary improper-integral convergence.","hint":"Opposite infinite tails cannot be declared convergent by canceling one another."}],"calculus-chapter-07-review-7-concept-check-1":[{"label":"a","selectionPrompt":"If f has an infinite discontinuity at a, how is ∫ₐᵇ f(x) dx defined?","answer":"limₜ→ₐ⁺ ∫ₜᵇ f(x) dx, with a finite limit required for convergence.","distractors":["limₜ→ₐ⁻ ∫ₜᵇ f(x) dx, even when f is only defined to the right of a.","The value f(a)(b − a), even though f(a) is infinite.","∫ₐᵇ f(x) dx with the value at a simply set to 0 and no limit taken."],"explanation":"Approach the singular lower endpoint from inside the interval.","hint":"Which side of a belongs to the interval being integrated?"},{"label":"b","selectionPrompt":"If f has an infinite discontinuity at b, how is ∫ₐᵇ f(x) dx defined?","answer":"limₜ→ᵦ⁻ ∫ₐᵗ f(x) dx, with a finite limit required for convergence.","distractors":["limₜ→ᵦ⁺ ∫ₐᵗ f(x) dx, even if f is only defined to the left of b.","The value f(b)(b − a), with no limit.","The finite integral ending at (a + b)/2, ignoring the remaining interval."],"explanation":"Approach the singular upper endpoint from inside the interval.","hint":"Keep the finite lower endpoint fixed and move the upper endpoint toward the singularity."},{"label":"c","selectionPrompt":"If f has an infinite discontinuity at c with a < c < b, how is ∫ₐᵇ f defined?","answer":"Split at c, define each side by its appropriate one-sided limit, and require both integrals to converge before adding them.","distractors":["Use only a symmetric limit around c; canceling opposite divergences always counts as convergence.","Ignore f on the entire right half of the interval.","Substitute f(c) = 0 and apply the ordinary integral definition without limits."],"explanation":"An interior singularity creates two separate improper integrals, both of which must converge.","hint":"Treat each approach to the singular point independently."}],"calculus-chapter-08-review-3-concept-check-1":[{"label":"","selectionPrompt":"How can hydrostatic force against a submerged vertical wall be found?","answer":"Integrate pressure times the area of thin horizontal strips: F = ∫ ρg·depth(y)·width(y) dy for constant fluid density ρ.","distractors":["Multiply the pressure at the water surface by the entire wall area, regardless of depth.","Integrate the wall’s width alone; fluid density and depth do not affect force.","Use F = ∫ ρg/depth(y) dy, so pressure decreases with depth."],"explanation":"Hydrostatic pressure is ρg times depth; multiplying by a strip area and integrating sums the strip forces.","hint":"Pressure changes with depth, so use strips having nearly constant depth."}],"calculus-chapter-08-review-4-concept-check-1":[{"label":"a","selectionPrompt":"What is the physical significance of a thin plate’s center of mass?","answer":"The balance point, where the plate’s mass can be treated as concentrated for calculating its first moments.","distractors":["The point that always has the greatest density.","The midpoint of the plate’s bounding rectangle for every shape and density.","The point that must lie on the plate’s boundary."],"explanation":"Coordinates of the center of mass are density-weighted mean positions; balance depends on the full mass distribution.","hint":"Think about balancing the plate rather than finding its highest-density point."}],"calculus-chapter-08-review-5-concept-check-1":[{"label":"","selectionPrompt":"What does the Theorem of Pappus say?","answer":"For a plane region rotated about an external coplanar axis, the volume is its area times the distance traveled by its centroid.","distractors":["The volume equals the region’s perimeter times the distance traveled by its centroid.","The volume equals the region’s area times its maximum distance from the axis.","The volume equals its area times its centroid’s distance from the axis, without the factor 2π for a full revolution."],"explanation":"For a full revolution the centroid travels 2πd; the axis must not pass through the region’s interior.","hint":"Combine the region’s area with the centroid’s full circular travel distance."}],"calculus-chapter-08-review-7-concept-check-1":[{"label":"a","selectionPrompt":"What is cardiac output?","answer":"The volume of blood pumped by the heart per unit time.","distractors":["The pressure of blood in the heart, measured as force per area.","The total number of heartbeats over a person’s lifetime.","The concentration of dye in one blood sample."],"explanation":"Cardiac output is a volumetric flow rate, not pressure, concentration, or beat count.","hint":"Consider what quantity flows and the time basis of its measurement."},{"label":"b","selectionPrompt":"How does the dye dilution method estimate cardiac output?","answer":"Inject a known dye mass A, measure its downstream concentration c(t) during passage, and estimate flow as A/∫ c(t) dt.","distractors":["Divide the peak dye concentration by the injected mass, ignoring the rest of the concentration curve.","Multiply the injected mass by the total time, without concentration measurements.","Use only the patient’s pulse count; the dye measurement plays no role."],"explanation":"For approximately steady flow, injected dye mass equals flow times the concentration-time integral, with recirculation appropriately excluded.","hint":"Use conservation of dye mass: concentration multiplied by blood volume gives dye mass."}],"calculus-chapter-08-review-8-concept-check-1":[{"label":"","selectionPrompt":"What is a probability density function, and what properties must it have?","answer":"A nonnegative integrable f with ∫₋∞^∞ f(x) dx = 1; interval probabilities are integrals of f over those intervals.","distractors":["A function with f(x) between 0 and 1 whose value f(x) is the probability of the exact point x.","Any function with integral 0; negative values represent impossible outcomes.","A nonnegative function whose integral may be any positive number without normalization."],"explanation":"Probabilities are areas, so density cannot be negative and total area must be 1. A density value may exceed 1.","hint":"Probability is accumulated over intervals, not read directly from a density’s height."}],"calculus-chapter-08-review-9-concept-check-1":[{"label":"a","selectionPrompt":"What does ∫₀¹³⁰ f(x) dx mean for the stated weight density?","answer":"The probability that a randomly selected female college student’s weight is between 0 and 130 pounds.","distractors":["The expected weight of all female college students, in pounds.","The probability that the weight is exactly 130 pounds.","The number of female college students who weigh 130 pounds."],"explanation":"A probability density integrates over a weight interval to give the probability of that interval.","hint":"Read the bounds as possible weights, not times or counts."},{"label":"b","selectionPrompt":"What expression gives the mean of this weight density?","answer":"μ = ∫₋∞^∞ x f(x) dx, provided the mean exists; equivalently integrate over its support.","distractors":["μ = ∫₋∞^∞ f(x) dx, which always gives the mean weight.","μ = f(130), the density height at 130 pounds.","μ = ∫₋∞^∞ x dx, without weighting by the density."],"explanation":"The mean is a probability-weighted average of the weight variable.","hint":"A weighted average multiplies each possible value by its probability density."},{"label":"c","selectionPrompt":"How can the median of the weight density be found?","answer":"Find m with ∫₋∞ᵐ f(x) dx = 1/2; for nonnegative weights the lower bound can be 0.","distractors":["Find the x at which f(x) is largest; this always gives the median.","Find m such that f(m) = 1/2, regardless of the accumulated area.","Find the mean ∫ x f(x) dx; every distribution has equal mean and median."],"explanation":"The median splits total probability into halves, rather than splitting the density height.","hint":"Look for the point dividing area under the density into two equal portions."}],"calculus-chapter-08-review-10-concept-check-1":[{"label":"","selectionPrompt":"What is a normal distribution, and what does its standard deviation signify?","answer":"A density f(x) = exp(−(x − μ)²/(2σ²))/(σ√(2π)), σ > 0; σ measures spread about the mean μ.","distractors":["A uniform density with no central peak; σ specifies its mean.","A density f(x) = exp(x − μ) over all real x; σ is its total probability.","A distribution concentrated at a single point for every σ > 0; σ measures the number of observations."],"explanation":"The normal density is a symmetric bell curve, centered at μ, with width controlled by σ.","hint":"Distinguish the location of the center from the distribution’s spread."}],"calculus-chapter-09-review-1-concept-check-1":[{"label":"a","selectionPrompt":"What is a differential equation?","answer":"An equation relating an unknown function to one or more of its derivatives.","distractors":["An equation that never contains derivatives.","A rule assigning exactly one number to every function, without any equation.","An inequality that compares only fixed constants."],"explanation":"A differential equation constrains how an unknown function and its rates of change are related.","hint":"Look for derivatives of the function being solved for."},{"label":"b","selectionPrompt":"What is the order of a differential equation?","answer":"The order of the highest derivative appearing in the equation.","distractors":["The largest exponent of the independent variable.","The number of terms on the left side.","The degree of the highest power of the dependent variable."],"explanation":"Order counts repeated differentiation, independently of algebraic powers.","hint":"Inspect the derivatives rather than the powers or number of terms."},{"label":"c","selectionPrompt":"What is an initial condition?","answer":"A prescribed value of the solution, or of a required derivative, at a specified initial value of the independent variable.","distractors":["The value of the solution at every point, given before solving.","A rule that sets all integration constants equal to zero regardless of data.","The coefficient of the highest derivative in the equation."],"explanation":"Initial data selects a particular solution from a family by fixing behavior at one starting point.","hint":"Think about the data needed to select one solution curve."}],"calculus-chapter-09-review-3-concept-check-1":[{"label":"","selectionPrompt":"What is a direction field for y′ = F(x, y)?","answer":"A pattern of short line segments at points (x, y), each with slope F(x, y), indicating local solution directions.","distractors":["A plot of heights F(x, y) that never uses tangent slopes.","A family of vertical lines whose slopes are all infinite.","The single solution curve through the origin, regardless of initial condition."],"explanation":"The differential equation prescribes a slope at each point; solution curves follow those local directions.","hint":"What does the derivative prescribe at a chosen point in the plane?"}],"calculus-chapter-09-review-4-concept-check-1":[{"label":"","selectionPrompt":"How does Euler’s method approximate a solution of y′ = F(x, y)?","answer":"Start with (x₀, y₀), then use xₙ₊₁ = xₙ + h and yₙ₊₁ = yₙ + hF(xₙ, yₙ), following short tangent steps.","distractors":["Use yₙ₊₁ = F(xₙ, yₙ) without adding the previous value or multiplying by a step size.","At every step choose a new random slope, independent of the equation.","Use the exact solution at each future point, so no approximation is needed."],"explanation":"Euler’s update is a local linear approximation using the current slope and a small input step.","hint":"Combine the current output with slope times the change in input."}],"calculus-chapter-09-review-5-concept-check-1":[{"label":"","selectionPrompt":"What is a separable differential equation, and how is it solved?","answer":"One expressible as dy/dx = g(x)h(y); separate variables and integrate, while checking equilibrium solutions where h(y) = 0.","distractors":["One in which x and y must occur only as x + y; solve by setting both derivatives to zero.","One expressible only as y″ + y = 0; solve by taking logarithms of x.","Any differential equation; divide by every y-dependent factor and discard its zero solutions."],"explanation":"Separation places each variable with its own differential. Dividing by h(y) can lose constant equilibrium solutions.","hint":"Keep track of any solutions excluded when dividing by a function of y."}],"calculus-chapter-09-review-6-concept-check-1":[{"label":"","selectionPrompt":"What is a first-order linear differential equation, and how is it solved?","answer":"It has form y′ + P(x)y = Q(x); multiply by the integrating factor exp(∫P(x) dx), integrate the resulting product derivative, then solve for y.","distractors":["It has form y′ + y² = Q(x); solve every case by multiplying by x.","It has form y″ + P(x)y = 0; solve by taking one square root.","It has form y′ + P(x)y = Q(x); solve by setting y′ equal to zero everywhere."],"explanation":"The integrating factor turns the left side into (μy)′, where μ′ = Pμ.","hint":"Choose a factor that makes the product rule reproduce both terms on the left."}],"calculus-chapter-09-review-7-concept-check-1":[{"label":"b","selectionPrompt":"When does the natural growth population model fit?","answer":"When resources are effectively unlimited and the per-capita growth rate is approximately constant.","distractors":["When every population is forced toward a finite carrying capacity by crowding.","When the total number added each year is fixed independently of population.","When growth depends only on the population’s second derivative."],"explanation":"Natural growth assumes P′ = kP, giving a constant relative growth rate.","hint":"The model compares growth rate with current population size."}],"calculus-chapter-09-review-8-concept-check-1":[{"label":"b","selectionPrompt":"When is a logistic population model appropriate?","answer":"When the per-capita growth rate decreases approximately linearly with population size because resources impose a carrying capacity.","distractors":["When the per-capita growth rate stays constant for arbitrarily large populations.","When the population gains the same fixed number each year regardless of its size.","When there is no carrying capacity and growth accelerates without limit."],"explanation":"The factor 1 − P/K reduces relative growth as the population approaches carrying capacity K.","hint":"Think about how crowding changes the growth rate per individual."}],"calculus-chapter-10-review-1-concept-check-1":[{"label":"a","selectionPrompt":"What is a parametric curve?","answer":"The set traced by (x(t), y(t)) as a parameter t ranges through an interval.","distractors":["Only a curve expressible as a single-valued y = f(x).","A fixed point with no dependence on a parameter.","The set of every point in the plane, regardless of the coordinate functions."],"explanation":"Both coordinates depend on the parameter; such curves can loop or fail the vertical line test.","hint":"Follow a moving point whose two coordinates change with the same parameter."}],"calculus-chapter-10-review-6-concept-check-1":[{"label":"a","selectionPrompt":"What is the geometric definition of a parabola?","answer":"The set of points equidistant from a fixed focus and a fixed line called the directrix, with the focus off that line.","distractors":["The set of points at a fixed distance from one center.","The set of points whose distances to two foci have a fixed sum.","The set of points whose distances to two foci have a fixed nonzero absolute difference."],"explanation":"A parabola compares distance to a point with perpendicular distance to a line.","hint":"Which conic uses one focus and a line rather than two foci?"}],"calculus-chapter-10-review-7-concept-check-1":[{"label":"a","selectionPrompt":"How is an ellipse defined in terms of foci?","answer":"The set of points whose distances to two fixed foci have a constant sum greater than the distance between the foci.","distractors":["The set of points whose distances to two foci have a constant nonzero absolute difference.","The set of points equidistant from a focus and a directrix.","The set of all points on the perpendicular bisector of the line joining the foci."],"explanation":"The fixed sum determines a closed oval; the stated inequality avoids a degenerate line segment.","hint":"Ask whether the ellipse preserves a sum or a difference of the two distances."}],"calculus-chapter-10-review-8-concept-check-1":[{"label":"a","selectionPrompt":"How is a hyperbola defined in terms of foci?","answer":"The set of points whose distances to two fixed foci have a constant nonzero absolute difference smaller than the distance between the foci.","distractors":["The set of points whose distances to two foci have a constant sum greater than the distance between the foci.","The set of points equidistant from a focus and a line.","The set of points at a fixed distance from a single center."],"explanation":"The absolute difference determines the two branches of a nondegenerate hyperbola.","hint":"Compare the two focal distances using the operation appropriate to a two-branch conic."}],"calculus-chapter-10-review-9-concept-check-1":[{"label":"a","selectionPrompt":"What is the eccentricity of a conic section?","answer":"The constant ratio of distance to a focus to distance to the corresponding directrix.","distractors":["The sum of the distances to two foci, measured in units of length.","The ratio of area to perimeter, which has units of length.","The slope of the tangent at the rightmost vertex."],"explanation":"Eccentricity is a dimensionless focus-directrix distance ratio characterizing the conic.","hint":"Use the focus-directrix definition and check that the ratio has no units."},{"label":"b","selectionPrompt":"What eccentricity values distinguish an ellipse, a parabola, and a hyperbola?","answer":"Ellipse: 0 < e < 1; parabola: e = 1; hyperbola: e > 1. A circle has e = 0 as a limiting ellipse.","distractors":["Ellipse: e > 1; parabola: e = 1; hyperbola: 0 < e < 1.","Ellipse: e = 1; parabola: e = 0; hyperbola: e < 0.","All three have e = 1; only their sizes differ."],"explanation":"The focus-directrix ratio below, equal to, or above 1 gives the three conic types.","hint":"Compare the focal distance with the directrix distance."}],"calculus-chapter-11-review-1-concept-check-1":[{"label":"a","selectionPrompt":"What is a convergent sequence?","answer":"A sequence whose terms approach a finite real limit as n → ∞.","distractors":["A sequence whose terms are all distinct, regardless of their limiting behavior.","A sequence whose terms grow without bound.","A sequence whose sum of all terms is necessarily finite."],"explanation":"Sequence convergence concerns the limit of terms; convergence of their series is a separate question.","hint":"Distinguish the individual terms from their running sums."},{"label":"b","selectionPrompt":"What is a convergent series?","answer":"A series whose sequence of partial sums approaches a finite limit.","distractors":["Any series whose terms approach zero, with no other condition.","Any series having bounded individual terms.","A series whose partial sums grow without bound."],"explanation":"The value of an infinite series is the limiting total of its partial sums; terms tending to zero alone do not suffice.","hint":"Which sequence represents progressively accumulated totals?"},{"label":"c","selectionPrompt":"What does limₙ→∞ aₙ = 3 mean?","answer":"For every ε > 0, all sufficiently late terms satisfy |aₙ − 3| < ε.","distractors":["Every term of the sequence must equal 3 exactly.","The sum of all sequence terms equals 3.","Only the first three terms must be close to zero."],"explanation":"A sequence limit describes arbitrarily close eventual proximity, not exact equality of all terms.","hint":"The condition should involve all sufficiently large indices."},{"label":"d","selectionPrompt":"What does Σₙ₌₁^∞ aₙ = 3 mean?","answer":"The partial sums sₙ = a₁ + ··· + aₙ approach 3 as n → ∞.","distractors":["The individual terms aₙ approach 3 as n → ∞.","Each partial sum must equal 3 exactly.","The third term a₃ equals 0 and all later terms are ignored."],"explanation":"The equality specifies the limit of accumulated sums, rather than the limit of individual terms.","hint":"An infinite sum is defined through finite sums taken farther and farther."}],"calculus-chapter-11-review-2-concept-check-1":[{"label":"a","selectionPrompt":"What is a bounded sequence?","answer":"There exist finite constants m and M with m ≤ aₙ ≤ M for every n.","distractors":["There is a finite M with aₙ ≤ M, but no lower bound is required.","The sequence has only finitely many terms.","The terms must all have the same value."],"explanation":"Bounded means a uniform finite upper and lower bound for all terms.","hint":"All terms must fit inside one fixed finite interval."},{"label":"b","selectionPrompt":"What is a monotonic sequence?","answer":"A sequence that is nondecreasing throughout or nonincreasing throughout.","distractors":["A sequence that alternates direction at every step.","Any sequence whose terms all have the same sign.","A sequence with a finite limit, whether or not it repeatedly rises and falls."],"explanation":"Monotonicity requires a consistent direction of successive changes; equal successive values are allowed.","hint":"Compare each term with the next one and keep the same inequality direction."},{"label":"c","selectionPrompt":"What can be concluded about a bounded monotonic sequence?","answer":"It converges to a finite limit.","distractors":["It must eventually become exactly constant.","It necessarily diverges to positive infinity.","Its series of terms necessarily converges."],"explanation":"The Monotonic Sequence Theorem gives sequence convergence, not convergence of the associated series.","hint":"A persistent direction of change cannot escape a fixed bound."}],"calculus-chapter-11-review-3-concept-check-1":[{"label":"a","selectionPrompt":"What is a geometric series, when does it converge, and what is its sum?","answer":"a + ar + ar² + ··· with a ≠ 0 converges exactly when |r| < 1, and then its sum is a/(1 − r).","distractors":["a + ar + ar² + ··· with a ≠ 0 converges exactly when |r| > 1, with sum a/(1 − r).","a + ar + ar² + ··· with a ≠ 0 converges for every r, with sum a/(1 + r).","a + ar + ar² + ··· with a ≠ 0 converges only at r = 1, with sum a."],"explanation":"For a nonzero first term, powers rⁿ shrink to zero precisely when |r| < 1, yielding the geometric-sum limit.","hint":"The common ratio must make successive powers decay rather than grow."},{"label":"b","selectionPrompt":"What is a p-series, and when does it converge?","answer":"Σₙ₌₁^∞ 1/nᵖ; it converges exactly when p > 1.","distractors":["Σₙ₌₁^∞ 1/nᵖ; it converges exactly when p ≥ 1.","Σₙ₌₁^∞ pⁿ; it converges exactly when p > 1.","Σₙ₌₁^∞ 1/nᵖ; it converges for every p > 0."],"explanation":"The integral comparison gives the strict threshold p > 1; the harmonic series at p = 1 diverges.","hint":"Use the harmonic series as the boundary case."}],"calculus-chapter-11-review-6-concept-check-1":[{"label":"a","selectionPrompt":"What is an absolutely convergent series?","answer":"A series Σ aₙ for which Σ |aₙ| converges.","distractors":["A series whose terms all have the same sign, even if its sum diverges.","A series that converges only because positive and negative terms cancel, while Σ |aₙ| diverges.","Any series whose individual terms are bounded."],"explanation":"Absolute convergence is tested by summing the magnitudes of terms.","hint":"Remove the signs before testing convergence."},{"label":"b","selectionPrompt":"What can be said about an absolutely convergent series?","answer":"It converges, and every rearrangement of its terms converges to the same sum.","distractors":["It diverges whenever any term is negative.","Its terms must all be positive.","Its rearrangements can have arbitrary sums despite absolute convergence."],"explanation":"Absolute convergence controls the total magnitude of the tails, ensuring convergence and rearrangement invariance.","hint":"Absolute summability prevents uncontrolled cancellation."},{"label":"c","selectionPrompt":"What is a conditionally convergent series?","answer":"Σ aₙ converges but Σ |aₙ| diverges.","distractors":["Both Σ aₙ and Σ |aₙ| converge.","Both Σ aₙ and Σ |aₙ| diverge.","Σ |aₙ| converges while Σ aₙ diverges."],"explanation":"Conditional convergence relies on cancellation and lacks absolute convergence.","hint":"Compare the original signed series with its series of magnitudes."}],"calculus-chapter-11-review-8-concept-check-1":[{"label":"b","selectionPrompt":"What is the radius of convergence R of a power series centered at a?","answer":"The boundary distance for convergence: the series converges for |x − a| < R and diverges for |x − a| > R; endpoints require separate tests.","distractors":["The distance R where both endpoints always converge automatically.","The center a of the series, regardless of coefficient values.","The number of terms in the series before every coefficient becomes zero."],"explanation":"The radius describes the interior convergence range; boundary behavior is not determined by R alone. R can be 0 or ∞.","hint":"Separate the interior, exterior, and boundary of the convergence region."},{"label":"c","selectionPrompt":"What is the interval of convergence of a real power series?","answer":"The set of real x values where the series converges, including whichever boundary endpoints pass their own convergence tests.","distractors":["Always the open interval (a − R, a + R), with neither endpoint permitted.","Always the closed interval [a − R, a + R], without testing endpoints.","The set of real x values where the series diverges."],"explanation":"Interior convergence follows from the radius; endpoint inclusion is determined separately.","hint":"The interval includes exactly those points where the actual series converges."}],"calculus-chapter-12-review-1-concept-check-1":[{"label":"","selectionPrompt":"What is the difference between a vector and a scalar?","answer":"A vector has magnitude and direction; a scalar has magnitude represented by a single number without a direction.","distractors":["A vector is always positive; a scalar is always negative.","A scalar has direction but no magnitude; a vector has neither.","Vectors and scalars are interchangeable names for the same object."],"explanation":"Direction distinguishes vector quantities such as displacement from scalar quantities such as temperature.","hint":"Compare displacement with distance, or velocity with speed."}],"calculus-chapter-12-review-2-concept-check-1":[{"label":"","selectionPrompt":"How are two vectors added geometrically and algebraically?","answer":"Place them head-to-tail (or use a parallelogram) and draw the resultant; algebraically add corresponding components.","distractors":["Place them tail-to-tail and subtract their lengths; algebraically multiply corresponding components.","Add their magnitudes and keep the first direction, regardless of their angle.","Cross them at right angles and divide corresponding components."],"explanation":"Vector addition combines directed displacements; matching component sums give the same resultant.","hint":"Follow the first displacement and then the second."}],"calculus-chapter-12-review-3-concept-check-1":[{"label":"","selectionPrompt":"How is ca related to a geometrically and algebraically?","answer":"Its magnitude is |c||a|; for c > 0 its direction agrees, for c < 0 it reverses, and each component is multiplied by c (c = 0 gives the zero vector).","distractors":["Its magnitude is c + |a|, and its direction always stays the same.","Its magnitude is |a|/|c|, and every component is divided by c.","Its magnitude is |c||a|, but its direction reverses for every positive c."],"explanation":"Scalar multiplication stretches or shrinks a vector, with a negative scalar reversing its direction.","hint":"Consider the scalar’s absolute value separately from its sign."}],"calculus-chapter-12-review-4-concept-check-1":[{"label":"","selectionPrompt":"How do you find the vector from a point P to a point Q?","answer":"Subtract the coordinates of the starting point from those of the endpoint: PQ = Q − P.","distractors":["Subtract the endpoint coordinates from the starting coordinates: PQ = P − Q.","Add P and Q component by component.","Multiply their matching coordinates and keep only one scalar."],"explanation":"Endpoint minus starting point gives the displacement that takes P to Q.","hint":"Check which direction the vector should point."}],"calculus-chapter-12-review-6-concept-check-1":[{"label":"","selectionPrompt":"How are dot products useful?","answer":"They determine angles and perpendicularity, scalar/vector projections, and work by a constant force.","distractors":["They always produce a vector perpendicular to both inputs, giving parallelogram area.","They determine an oriented normal vector by the right-hand rule.","They create a vector field from an arbitrary scalar with no directions specified."],"explanation":"The dot product combines component alignment into a scalar, making it useful for angles, projections, and work.","hint":"Think about the factor cos θ and whether the output is a scalar or a vector."}],"calculus-chapter-12-review-9-concept-check-1":[{"label":"","selectionPrompt":"How are cross products useful?","answer":"They provide normal vectors, oriented area vectors, and physical quantities such as torque.","distractors":["They directly give the scalar work done by a force along a displacement.","They give a scalar projection onto the first vector.","They always give a vector parallel to both nonparallel inputs."],"explanation":"The cross product is perpendicular to both vectors, has magnitude |a||b|sin θ, and carries orientation.","hint":"Think about a perpendicular direction and the area spanned by two vectors."}],"calculus-chapter-12-review-11-concept-check-1":[{"label":"","selectionPrompt":"How can a vector perpendicular to a plane be found?","answer":"Take the cross product of two nonparallel vectors lying in the plane.","distractors":["Add any two vectors in the plane; their sum is always perpendicular to it.","Take the dot product of two plane vectors; the resulting scalar is a normal vector.","Choose any vector in the plane as its normal."],"explanation":"Two nonparallel plane vectors span the plane, and their cross product is perpendicular to both.","hint":"You need a vector operation that returns a direction perpendicular to two given directions."}],"calculus-chapter-12-review-15-concept-check-1":[{"label":"a","selectionPrompt":"How can you tell whether two nonzero vectors are parallel?","answer":"One is a scalar multiple of the other; in three dimensions their cross product is zero.","distractors":["Their dot product must be zero.","Their sum must be the zero vector for every parallel pair.","Their cross product has the largest possible magnitude."],"explanation":"Parallel vectors point along the same line, possibly in opposite directions. The nonzero condition avoids an undefined direction.","hint":"Ask whether scaling one vector can produce the other."},{"label":"b","selectionPrompt":"How can you tell whether two nonzero vectors are perpendicular?","answer":"Their dot product is zero.","distractors":["One must be a nonzero scalar multiple of the other.","Their cross product must be zero.","Their magnitudes must be equal."],"explanation":"For nonzero vectors a·b = |a||b|cos θ vanishes at θ = π/2.","hint":"Use the vector product involving cosine of the angle."},{"label":"c","selectionPrompt":"How can you tell whether two planes are parallel?","answer":"Their nonzero normal vectors are parallel (with distinct parallel planes having different locations).","distractors":["Their normal vectors are perpendicular.","They share any one point, which guarantees distinct parallel planes.","They have equal distances from the origin, regardless of normal directions."],"explanation":"Parallel normals give the same plane orientation; equations or points distinguish coincident from distinct parallel planes.","hint":"A normal encodes the orientation of a plane."}],"calculus-chapter-12-review-18-concept-check-1":[{"label":"","selectionPrompt":"What are traces of a surface, and how do you find them?","answer":"Intersections of the surface with planes; set one coordinate to a constant to obtain coordinate-plane-parallel traces.","distractors":["Only the points where the surface meets the x-, y-, and z-axes.","The volume enclosed by the surface, computed by a triple integral.","The vectors perpendicular to the surface at every point."],"explanation":"A trace is a cross-sectional curve (or other intersection), useful for reconstructing a surface’s shape.","hint":"Imagine slicing the surface with a plane."}],"calculus-chapter-13-review-1-concept-check-1":[{"label":"","selectionPrompt":"What is a vector function, and how are its derivative and integral found?","answer":"A function whose outputs are vectors; differentiate or integrate its component functions, with a vector constant for an indefinite integral.","distractors":["A scalar-valued function whose derivative must be a cross product.","A fixed vector that can never depend on a parameter.","A function whose components must all be equal and whose derivative is always zero."],"explanation":"Vector differentiation and integration are performed component by component.","hint":"Treat each component as an ordinary function of the parameter."}],"calculus-chapter-13-review-2-concept-check-1":[{"label":"","selectionPrompt":"What connects vector functions and space curves?","answer":"A continuous position vector r(t) traces a space curve; its components give the curve’s parametric coordinates.","distractors":["Every vector function traces only a straight line.","A space curve is represented by one scalar coordinate with the other two always zero.","Vector functions describe only vectors fixed at the origin, never moving positions."],"explanation":"The tip of the position vector moves through space as its parameter varies.","hint":"Interpret the output vector as the location of a moving point."}],"calculus-chapter-13-review-6-concept-check-1":[{"label":"a","selectionPrompt":"What is curvature?","answer":"The magnitude of the rate of change of the unit tangent with respect to arc length: κ = |dT/ds|.","distractors":["The rate of change of the position’s magnitude with respect to time.","The speed |r′(t)|, regardless of whether the curve bends.","The signed height of the curve above the xy-plane."],"explanation":"Curvature measures how rapidly the direction of the curve changes per unit distance traveled, independently of parameter speed.","hint":"Compare tangent directions as you move a fixed small distance along the curve."}],"calculus-chapter-13-review-7-concept-check-1":[{"label":"b","selectionPrompt":"What are the normal plane, osculating plane, and osculating circle at a point where curvature is nonzero?","answer":"The normal plane is perpendicular to T; the osculating plane is spanned by T and N; the osculating circle has radius 1/κ and center r + N/κ.","distractors":["The normal plane is spanned by T and N; the osculating plane is perpendicular to T; the circle has radius κ.","The normal plane is always the xy-plane; the osculating circle always has radius 1.","The osculating plane is perpendicular to N and the circle’s center is always the origin."],"explanation":"The normal plane contains N and B, while the osculating plane contains T and N and supports the best locally fitting circle.","hint":"Keep the tangent, principal normal, and binormal directions distinct."}],"calculus-chapter-13-review-8-concept-check-1":[{"label":"a","selectionPrompt":"How are velocity, speed, and acceleration obtained from a particle’s position vector r(t)?","answer":"Velocity is r′(t), speed is |r′(t)|, and acceleration is r″(t).","distractors":["Velocity is |r′(t)|, speed is r′(t), and acceleration is r(t).","Velocity is r(t), speed is |r(t)|, and acceleration is r′(t).","Velocity is r″(t), speed is |r″(t)|, and acceleration is ∫r(t) dt."],"explanation":"Velocity and acceleration are vectors; speed is the nonnegative magnitude of velocity.","hint":"Track derivatives and distinguish directed motion from its magnitude."}],"calculus-chapter-14-review-1-concept-check-1":[{"label":"a","selectionPrompt":"What is a function of two variables?","answer":"A rule assigning exactly one real value f(x, y) to each allowed ordered pair (x, y) in its domain.","distractors":["A rule assigning exactly two output values to each input x.","A rule requiring x and y to be equal at every input.","A curve in a plane with exactly one real input and no output rule."],"explanation":"The input is an ordered pair; the output remains a single real number.","hint":"Count input coordinates separately from the number of outputs."},{"label":"b","selectionPrompt":"Which three methods can visualize a function of two variables?","answer":"A graph z = f(x, y), a contour map of level curves, and a table of function values.","distractors":["Only an ordinary y = f(x) curve, its inverse, and the x-axis.","A list of slopes at one point, a single output value, and the origin.","Three unrelated graphs in which f does not appear."],"explanation":"Surface graphs show heights, contours group equal outputs, and tables display sampled outputs.","hint":"Think of heights, equal-height slices, and sampled data."}],"calculus-chapter-14-review-2-concept-check-1":[{"label":"","selectionPrompt":"What is a function of three variables, and how can it be visualized?","answer":"A rule assigning one real value to each allowed triple (x, y, z); visualize it with level surfaces f(x, y, z) = k or slices.","distractors":["A rule assigning exactly three outputs to one input; its ordinary graph always lies in a two-dimensional plane.","A rule defined only on the three coordinate axes, with no values elsewhere.","A vector field whose output must always be the position vector (x, y, z)."],"explanation":"The full graph would require four coordinates, so level surfaces and slices convey the dependence in three-dimensional space.","hint":"Consider how many coordinates a graph of three inputs plus one output would need."}],"calculus-chapter-14-review-3-concept-check-1":[{"label":"","selectionPrompt":"What does lim_(x,y)→(a,b) f(x, y) = L mean, and how can nonexistence be shown?","answer":"f approaches L as (x, y) approaches (a, b) along every allowed approach; different limits along two paths prove nonexistence.","distractors":["A limit of L along one chosen path proves the two-variable limit exists.","f(a, b) must equal L; nearby values are irrelevant.","Checking the x-axis approach alone is sufficient for every function."],"explanation":"A multivariable limit must be independent of the approach path; a disagreement between paths is enough to disprove it.","hint":"The input can approach the point from infinitely many directions and along curved paths."}],"calculus-chapter-14-review-4-concept-check-1":[{"label":"a","selectionPrompt":"What does continuity of f at (a, b) mean?","answer":"f(a, b) is defined and lim_(x,y)→(a,b) f(x, y) = f(a, b).","distractors":["Only f(a, b) must exist, with no condition on nearby values.","Both partial derivatives must exist, which always suffices for continuity.","The limit must be 0, regardless of the actual value f(a, b)."],"explanation":"The nearby limiting value must agree with the actual value at the point.","hint":"Use the same value-versus-limit idea as in one variable, with all approaches considered."},{"label":"b","selectionPrompt":"What does continuity of f on ℝ² imply about its graph?","answer":"The surface z = f(x, y) has no jumps or holes caused by discontinuities, but it need not have a tangent plane everywhere.","distractors":["The surface must be a plane.","The surface must have continuous partial derivatives of every order.","The surface may have arbitrary jumps as long as its domain is ℝ²."],"explanation":"Continuity prevents discontinuous changes in height but does not guarantee differentiability.","hint":"An unbroken surface can still have corners or creases."}],"calculus-chapter-14-review-6-concept-check-1":[{"label":"","selectionPrompt":"What does Clairaut’s Theorem say?","answer":"If the mixed second partial derivatives are continuous near (a, b), then fₓᵧ(a, b) = fᵧₓ(a, b).","distractors":["Mixed partials are equal for every function with no existence or continuity conditions.","fₓₓ = fᵧᵧ for every twice differentiable function.","fₓᵧ = −fᵧₓ whenever both are continuous."],"explanation":"The theorem gives equality of mixed partials under continuity hypotheses; pure second partials need not be equal.","hint":"Focus on changing the order of differentiation, not changing which variables are used."}],"calculus-chapter-14-review-8-concept-check-1":[{"label":"","selectionPrompt":"What is the linearization at (a, b), its approximation, and its geometry?","answer":"L(x, y) = f(a, b) + fₓ(a, b)(x − a) + fᵧ(a, b)(y − b); for differentiable f, f ≈ L near (a, b), and z = L is its tangent plane.","distractors":["L(x, y) = fₓ(a, b)x + fᵧ(a, b)y always, omitting the base value and offsets; it is always the exact surface.","L(x, y) = f(a, b) + fₓₓ(a, b)(x − a)²; it is the normal plane.","L(x, y) = f(a, b) only, regardless of nonzero slopes; it is the osculating sphere."],"explanation":"The linearization combines the base height with first-order changes in each input.","hint":"Anchor an affine plane at the base point and match both first-order slopes."}],"calculus-chapter-14-review-9-concept-check-1":[{"label":"a","selectionPrompt":"What does differentiability of f at (a, b) mean?","answer":"Δf = fₓ(a, b)Δx + fᵧ(a, b)Δy + an error whose ratio to √(Δx² + Δy²) tends to 0.","distractors":["Both partial derivatives exist, which alone always guarantees differentiability.","f(a, b) is finite, with no further local condition.","f is constant along each coordinate axis, regardless of other approaches."],"explanation":"Differentiability requires one linear map to approximate all sufficiently small input changes with smaller-order error.","hint":"The approximation must work uniformly for combined changes, not only along the coordinate axes."},{"label":"b","selectionPrompt":"What is a common sufficient way to verify differentiability?","answer":"Show the first partial derivatives exist near the point and are continuous there.","distractors":["Show only that the function has a value at the point.","Show only that one partial derivative exists at the point.","Show that the two partial derivatives are equal, without any continuity condition."],"explanation":"Continuity of the first partials in a neighborhood gives a standard sufficient criterion; it is not necessary in every case.","hint":"Look for a regularity condition on both first partial derivatives nearby."}],"calculus-chapter-14-review-14-concept-check-1":[{"label":"a","selectionPrompt":"What is the gradient of a function of two or three variables?","answer":"∇f is the vector of first partial derivatives: ⟨fₓ, fᵧ⟩ or ⟨fₓ, fᵧ, f_z⟩.","distractors":["∇f is the scalar sum fₓ + fᵧ + f_z.","∇f is the vector of input coordinates ⟨x, y, z⟩ for every f.","∇f is the determinant of the second-derivative matrix."],"explanation":"The gradient collects rates of change in each coordinate direction into a vector.","hint":"Each component should measure change along its own input axis."},{"label":"b","selectionPrompt":"For differentiable f and unit direction u, how is Dᵤf expressed using the gradient?","answer":"Dᵤf = ∇f · u.","distractors":["Dᵤf = ∇f × u.","Dᵤf = |∇f| for every direction u.","Dᵤf = f|u|, independently of the partial derivatives."],"explanation":"The dot product projects the gradient onto a unit direction, producing the scalar rate per unit distance.","hint":"A directional rate is the component of the gradient along that direction."},{"label":"c","selectionPrompt":"What is the geometric significance of a nonzero gradient?","answer":"It is perpendicular to the level curve or surface and points in the direction of greatest increase; its magnitude is the maximum directional derivative.","distractors":["It is tangent to the level curve and points toward greatest decrease.","It points in the direction of the smallest positive coordinate regardless of f.","It is perpendicular to every possible direction and all directional derivatives vanish."],"explanation":"Tangential motion along a level set has zero first-order change; the gradient gives the normal steepest-ascent direction.","hint":"Compare motion along a constant-value contour with motion crossing contours most rapidly."}],"calculus-chapter-14-review-15-concept-check-1":[{"label":"a","selectionPrompt":"What does a local maximum at (a, b) mean?","answer":"f(a, b) ≥ f(x, y) for every domain point sufficiently close to (a, b).","distractors":["f(a, b) ≥ f(x, y) for all domain points, regardless of distance; this is required for every local maximum.","f(a, b) ≤ f(x, y) for all sufficiently nearby domain points.","fₓ(a, b) is the largest partial derivative in the domain."],"explanation":"Local comparison is restricted to a neighborhood, and equality is allowed.","hint":"Pay attention to both the inequality direction and the word local."},{"label":"b","selectionPrompt":"What does an absolute maximum at (a, b) mean?","answer":"f(a, b) ≥ f(x, y) for every point (x, y) in the domain.","distractors":["f(a, b) exceeds nearby values only; distant larger values are allowed.","f(a, b) ≤ f(x, y) for every domain point.","f(a, b) has the largest absolute value, even if it is the most negative value."],"explanation":"An absolute maximum compares the function’s value with all domain values, not their magnitudes.","hint":"Absolute refers to the full domain, not to taking absolute values."},{"label":"c","selectionPrompt":"What does a local minimum at (a, b) mean?","answer":"f(a, b) ≤ f(x, y) for every domain point sufficiently close to (a, b).","distractors":["f(a, b) ≥ f(x, y) for every sufficiently nearby domain point.","f(a, b) must be zero.","f(a, b) is smaller than every value on the full domain; this stronger property is necessary for any local minimum."],"explanation":"A local minimum is no larger than nearby values, without claiming a global comparison.","hint":"Use the minimum inequality within a neighborhood."},{"label":"d","selectionPrompt":"What does an absolute minimum at (a, b) mean?","answer":"f(a, b) ≤ f(x, y) for every point in the domain.","distractors":["f(a, b) ≤ only nearby values; smaller distant values are allowed.","f(a, b) ≥ f(x, y) for every domain point.","|f(a, b)| is smallest, regardless of whether f(a, b) is the smallest signed value."],"explanation":"The comparison concerns signed function values over the entire domain.","hint":"Global minimum compares against every allowed input."},{"label":"e","selectionPrompt":"What is a saddle point in this setting?","answer":"A stationary point with nearby function values both above and below its value, so it is neither a local maximum nor a local minimum.","distractors":["A point whose value exceeds every other value in the domain.","Any point where fₓ = fᵧ = 0, which is automatically a saddle.","A point where nearby function values are all equal."],"explanation":"A zero gradient is only a candidate; a saddle has both upward and downward local behavior.","hint":"Check whether moving in different directions produces opposite kinds of change."}],"calculus-chapter-14-review-16-concept-check-1":[{"label":"a","selectionPrompt":"At an interior local maximum, what can be said about partial derivatives that exist?","answer":"Both first partial derivatives are zero, provided they exist at the point.","distractors":["Both partial derivatives must be strictly positive.","Both partial derivatives must be strictly negative.","The partial derivatives must always exist, including at a sharp peak."],"explanation":"Restricting f to either coordinate direction gives a one-variable local extremum and hence a zero derivative when it exists.","hint":"Use Fermat’s Theorem along each coordinate direction, keeping its existence condition."},{"label":"b","selectionPrompt":"What is a critical point of f in two variables?","answer":"A domain point where both first partials are zero, or where at least one first partial derivative does not exist.","distractors":["Any point where f itself is undefined.","Only a point where f has an absolute maximum.","Any point where fₓ and fᵧ have opposite signs."],"explanation":"Critical points extend the one-variable criterion while retaining the requirement that f is defined.","hint":"Examine the first derivatives only after verifying the point belongs to the domain."}],"calculus-chapter-14-review-18-concept-check-1":[{"label":"a","selectionPrompt":"What are a closed set and a bounded set in ℝ²?","answer":"A closed set contains all its boundary points; a bounded set is contained in some disk of finite radius.","distractors":["A closed set has no boundary; a bounded set must contain every boundary point.","A closed set is always finite; a bounded set is always open.","A closed set must be a rectangle; a bounded set must contain the origin."],"explanation":"Closed concerns inclusion of limit/boundary points; bounded concerns finite spatial extent.","hint":"Separate boundary inclusion from size."},{"label":"b","selectionPrompt":"What is the Extreme Value Theorem for functions of two variables?","answer":"A continuous f on a nonempty closed, bounded domain D attains both an absolute maximum and an absolute minimum on D.","distractors":["Every continuous f on an open domain attains both extrema.","Every differentiable f on an unbounded domain attains both extrema.","A continuous f attains both extrema only if its domain is a rectangle."],"explanation":"In ℝ², a closed, bounded domain is compact, so continuity guarantees attainment of extrema.","hint":"The theorem needs both continuity and a domain that includes its boundary and has finite extent."},{"label":"c","selectionPrompt":"How do you find the extreme values guaranteed on a closed, bounded domain?","answer":"Compare f at interior critical points with the extrema of f restricted to the boundary, including corners or boundary endpoints where present.","distractors":["Compare only interior points where both partials are zero and ignore the boundary.","Choose the boundary point farthest from the origin as the maximum.","Use only the value at the center of the domain."],"explanation":"Absolute extrema can lie in the interior or on the boundary; both must be considered.","hint":"The best value can be reached at the edge as well as in the interior."}],"calculus-chapter-15-review-9-concept-check-1":[{"label":"c","selectionPrompt":"When is changing to cylindrical or spherical coordinates useful?","answer":"When the region or integrand has rotational or spherical symmetry, making boundaries or the integrand simpler.","distractors":["Whenever the Jacobian can be omitted to reduce algebra.","Only when the original region is already a rectangular box.","Only when the integrand is identically zero."],"explanation":"Coordinate changes are chosen to fit geometry; the associated volume factor must still be included.","hint":"Choose coordinates that describe the boundaries naturally."}],"calculus-chapter-15-review-10-concept-check-1":[{"label":"a","selectionPrompt":"For x = g(u, v), y = h(u, v), what is the Jacobian?","answer":"∂(x, y)/∂(u, v) = gᵤhᵥ − gᵥhᵤ, the determinant of the derivative matrix.","distractors":["gᵤhᵥ + gᵥhᵤ, the sum of both diagonal products.","g(u, v) + h(u, v), the sum of the new coordinates.","gᵤ + hᵥ, the trace rather than the determinant."],"explanation":"The Jacobian determinant measures signed local area scaling under the coordinate transformation.","hint":"Write the two-by-two derivative matrix and take its determinant."}],"calculus-chapter-16-review-1-concept-check-1":[{"label":"","selectionPrompt":"What is a vector field, and which three examples have physical meaning?","answer":"A rule assigning a vector to each point in a region; examples include fluid velocity, gravitational force, and electric fields.","distractors":["A rule assigning one scalar to each point; examples are temperature, density, and pressure alone.","A single fixed vector with no position dependence, which cannot represent any field.","A curve assigning points only to time, with no vectors associated with positions."],"explanation":"Vector fields attach a magnitude and direction to locations; velocity and force fields are standard physical examples.","hint":"Ask whether each location receives a scalar value or a directed quantity."}],"calculus-chapter-16-review-2-concept-check-1":[{"label":"a","selectionPrompt":"What is a conservative vector field?","answer":"A vector field F for which F = ∇f for some scalar potential function f on its domain.","distractors":["A field whose vectors all have the same magnitude, whether or not a potential exists.","A field whose divergence is zero, which alone always makes it conservative.","A field whose arrows all point away from the origin, regardless of their formula."],"explanation":"Conservative means the field is the gradient of a scalar potential; other properties require hypotheses or describe different field behavior.","hint":"Look for a scalar function whose partial derivatives recover the field components."},{"label":"b","selectionPrompt":"What is a potential function for F?","answer":"A scalar function f satisfying ∇f = F.","distractors":["The scalar |F|, which is always a potential.","A vector function equal to curl F.","A scalar function whose gradient is zero regardless of F."],"explanation":"A potential recovers the vector field by differentiation; potentials can differ by a constant on a connected domain.","hint":"Which derivative operation turns a scalar function into a vector field?"}],"calculus-chapter-16-review-4-concept-check-1":[{"label":"a","selectionPrompt":"How is the line integral of F along an oriented smooth curve r(t), a ≤ t ≤ b, defined?","answer":"∫_C F · dr = ∫ₐᵇ F(r(t)) · r′(t) dt.","distractors":["∫_C F · dr = ∫ₐᵇ |F(r(t))||r′(t)| dt for every F, ignoring their relative directions.","∫_C F · dr = ∫ₐᵇ F(r(t)) × r′(t) dt, producing a vector.","∫_C F · dr = F(r(b)) − F(r(a)), whether or not F has a potential."],"explanation":"The vector field is evaluated along the curve and dotted with its directed velocity; orientation is built into dr.","hint":"Replace dr with r′(t) dt, retaining the dot product and direction."},{"label":"b","selectionPrompt":"If F is a force field, what does ∫_C F · dr represent?","answer":"The work done by the force along the oriented curve C.","distractors":["The total length of C, regardless of the force.","The flux through an unspecified closed surface.","The maximum force magnitude on C."],"explanation":"The dot product selects the force component along displacement, and the integral accumulates work.","hint":"Compare the force direction with each small directed displacement."}],"calculus-chapter-16-review-5-concept-check-1":[{"label":"","selectionPrompt":"What does the Fundamental Theorem for Line Integrals say?","answer":"For a continuously differentiable potential f and a piecewise smooth curve C from A to B, ∫_C ∇f · dr = f(B) − f(A).","distractors":["Every vector-field line integral equals f(A) − f(B), even without a potential.","Every line integral of a scalar function with respect to arc length is zero on a closed curve.","The integral of ∇f depends only on the length of C, not the endpoint values."],"explanation":"Along a parametrized curve, the chain rule converts the integrand to the derivative of f along that curve.","hint":"Identify the potential and compare its endpoint values in the travel order."}],"calculus-chapter-16-review-6-concept-check-1":[{"label":"a","selectionPrompt":"What does path independence of ∫_C F · dr mean?","answer":"All admissible paths with the same starting and ending points give the same integral.","distractors":["All paths give zero regardless of endpoints.","Paths of equal length give the same integral even with different endpoints.","The integral is unchanged when direction is reversed, regardless of its value."],"explanation":"Path independence fixes endpoints and varies the route; reversing direction normally changes the sign.","hint":"Keep the starting and ending points fixed while comparing routes."},{"label":"b","selectionPrompt":"For a continuous field on an open connected domain, what does path independence imply?","answer":"The field is conservative: a scalar potential can be defined by integrating from a fixed base point.","distractors":["The field must be zero everywhere.","The field’s divergence must be nonzero everywhere.","The field has no potential, even though its integrals are path independent."],"explanation":"Path independence makes the accumulated integral from a base point a well-defined function of the endpoint whose gradient is F.","hint":"Try using the integral from one fixed point to the variable endpoint as a function."}],"calculus-chapter-16-review-9-concept-check-1":[{"label":"a","selectionPrompt":"For F = ⟨P, Q, R⟩ on ℝ³, what is curl F?","answer":"curl F = ∇ × F = ⟨Rᵧ − Q_z, P_z − Rₓ, Qₓ − Pᵧ⟩.","distractors":["curl F = ∇ · F = Pₓ + Qᵧ + R_z.","curl F = ⟨Pₓ, Qᵧ, R_z⟩, with no differences of mixed components.","curl F = ⟨P, Q, R⟩², defined by squaring each component."],"explanation":"Curl is the vector differential cross product, encoding local rotational tendency.","hint":"Use the cross-product pattern with differential operators and track the signs."},{"label":"b","selectionPrompt":"For F = ⟨P, Q, R⟩ on ℝ³, what is div F?","answer":"div F = ∇ · F = Pₓ + Qᵧ + R_z.","distractors":["div F = ∇ × F, a three-component vector.","div F = Pᵧ + Q_z + Rₓ, using cyclic but unmatched coordinates.","div F = P + Q + R, without differentiating."],"explanation":"Divergence is a scalar sum of each component’s derivative in its own coordinate direction.","hint":"The divergence uses a dot-product pattern and returns a scalar."}],"calculus-chapter-16-review-10-concept-check-1":[{"label":"","selectionPrompt":"How can a C¹ vector field be tested for being conservative?","answer":"On an open simply connected domain, test Pᵧ = Qₓ in ℝ² or curl F = 0 in ℝ³; alternatively find a potential directly. Without the domain hypothesis, these derivative tests need not suffice.","distractors":["Zero divergence always guarantees a potential on every domain.","Zero curl guarantees a potential on every domain, including those with holes, without further checks.","A field is conservative exactly when all component values are positive."],"explanation":"A curl-free C¹ field is conservative on an open simply connected domain; topology matters for sufficiency.","hint":"Check both the relevant cross partial derivatives and the shape of the domain."}],"calculus-chapter-16-review-11-concept-check-1":[{"label":"a","selectionPrompt":"What is a parametric surface, and what are its grid curves?","answer":"A surface described by r(u, v) = ⟨x(u, v), y(u, v), z(u, v)⟩; grid curves result from holding u or v constant.","distractors":["A surface described by one parameter only; grid curves require changing neither coordinate.","A set of isolated points with no parameter domain; grid curves are arbitrary straight lines.","A scalar function of time; grid curves are its maximum and minimum values."],"explanation":"Two parameters locate surface points; fixing one leaves a one-parameter curve on the surface.","hint":"Imagine following one row or one column of the parameter grid."}],"calculus-chapter-16-review-13-concept-check-1":[{"label":"a","selectionPrompt":"What is an oriented surface, and what is an example of a nonorientable surface?","answer":"A surface with a consistent continuous choice of unit normal direction; a Möbius strip is nonorientable.","distractors":["A surface whose normal is always the same fixed vector; a sphere is nonorientable.","Any surface with a boundary; every surface without a boundary is nonorientable.","A surface with positive area only; a flat disk is nonorientable."],"explanation":"Orientation chooses normals consistently over the surface. A Möbius strip reverses the normal after a circuit.","hint":"Can the normal direction be continued around every loop without reversing unexpectedly?"},{"label":"b","selectionPrompt":"How is the flux of a vector field F over an oriented surface with unit normal n defined?","answer":"∬_S F · n dS, integrating the signed normal component of F over the surface.","distractors":["∬_S |F| dS, ignoring which way F crosses the surface.","∬_S F × n dS, producing a vector tangent to the surface.","∮_∂S F · dr, integrating circulation around the boundary instead of flux."],"explanation":"The normal component measures directed crossing; reversing orientation reverses the signed flux.","hint":"Only the component perpendicular to the surface contributes to crossing it."}],"calculus-chapter-16-review-14-concept-check-1":[{"label":"","selectionPrompt":"What does Stokes’ Theorem say?","answer":"For a C¹ field and an oriented smooth surface S with positively oriented boundary C, ∮_C F · dr = ∬_S (curl F) · n dS.","distractors":["∮_C F · dr = ∬_S (div F) dS for every orientation.","∮_C F · dr = ∬_S F · n dS, equating circulation directly to flux of the same field.","The theorem applies only to surfaces with no boundary and makes every circulation nonzero."],"explanation":"Stokes relates circulation around the oriented boundary to curl flux through the surface, with compatible orientation.","hint":"Match circulation with the field operation measuring local rotation."}],"calculus-chapter-16-review-15-concept-check-1":[{"label":"","selectionPrompt":"What does the Divergence Theorem say?","answer":"For a C¹ field on a suitable solid E with closed outward-oriented boundary S, ∬_S F · n dS = ∭_E div F dV.","distractors":["Flux through any open surface equals a triple integral of curl F.","∬_S F · n dS = ∭_E |F| dV for every field.","The inward and outward orientations give the same signed flux with no sign change."],"explanation":"The theorem relates total outward flux through a closed boundary to divergence accumulated inside the solid.","hint":"Match a closed boundary’s outward flow with the volume rate of source or sink behavior."}],"calculus-chapter-16-review-16-concept-check-1":[{"label":"","selectionPrompt":"What do the four major integral theorems in this chapter have in common?","answer":"Each relates an integral over a region to an integral over its oriented boundary, linking accumulated derivatives with boundary values or flow.","distractors":["Each eliminates every orientation condition and applies to arbitrary discontinuous fields.","Each states that all boundary integrals are zero.","Each equates the maximum field magnitude with the region’s volume."],"explanation":"The Fundamental Theorem, Green, Stokes, and Divergence Theorems express a shared interior-derivative/boundary relationship under their own hypotheses.","hint":"Compare where each integral is taken: the region itself or its boundary."}],"calculus-chapter-17-review-2-concept-check-1":[{"label":"a","selectionPrompt":"What is an initial-value problem for a second-order differential equation?","answer":"The differential equation together with values y(x₀) and y′(x₀) specified at the same initial point.","distractors":["The equation together with y specified at two different endpoints, and no derivative value at the initial point.","The equation alone with no additional data.","The equation together with only one value y(x₀), which always determines a unique second-order solution."],"explanation":"A second-order initial-value problem specifies both position-like and slope-like initial data at one point.","hint":"Count the independent initial data and notice where they are prescribed."},{"label":"b","selectionPrompt":"What is a boundary-value problem for a second-order differential equation?","answer":"The differential equation together with conditions imposed at two different boundary points, such as y(a) and y(b).","distractors":["The equation together with y(x₀) and y′(x₀) at the same point only.","The equation with all coefficients forced to zero.","The equation with no conditions on the solution anywhere."],"explanation":"Boundary data constrains the solution at different endpoints rather than only at one initial point.","hint":"Distinguish where the two pieces of information are given."}],"calculus-chapter-14-review-13-concept-check-1":[{"label":"a","selectionPrompt":"What is the directional derivative in a unit direction u = ⟨a, b⟩, and how is it interpreted?","answer":"Dᵤf(x₀, y₀) = limₕ→₀ [f(x₀+ha, y₀+hb) − f(x₀, y₀)]/h; it is change per unit distance in direction u and the slope of the corresponding surface cross-section.","distractors":["Dᵤf = limₕ→₀ [f(x₀+h, y₀+h) − f(x₀, y₀)]/h for every u, so the direction has no effect.","Dᵤf = f(x₀, y₀)/|u|, which gives the surface height rather than a slope.","Dᵤf = ∫₀¹ f(x₀+ha, y₀+hb) dh, which gives the directional slope by averaging heights."],"explanation":"A unit vector makes h a signed distance along the chosen line; the limit measures the local height change per distance.","hint":"Parametrize a line through the point in the given direction, then form its difference quotient."}],"calculus-chapter-15-review-2-concept-check-1":[{"label":"b","selectionPrompt":"What is a type I region, and how is a double integral over it evaluated?","answer":"D = {(x, y): a ≤ x ≤ b, g₁(x) ≤ y ≤ g₂(x)}; integrate ∫ₐᵇ ∫_g₁(x)^g₂(x) f(x, y) dy dx.","distractors":["D = {(x, y): c ≤ y ≤ d, h₁(y) ≤ x ≤ h₂(y)}; this horizontal-slice form is called type I.","A type I region must be a rectangle with constant bounds for both variables.","A type I region allows each vertical line to intersect infinitely many disjoint y intervals without splitting the region."],"explanation":"Type I regions are vertically simple: a vertical slice runs from a lower to an upper y-bound, both functions of x.","hint":"Use vertical slices and integrate the variable whose bounds depend on the other first."},{"label":"c","selectionPrompt":"What is a type II region, and how is a double integral over it evaluated?","answer":"D = {(x, y): c ≤ y ≤ d, h₁(y) ≤ x ≤ h₂(y)}; integrate ∫_c^d ∫_h₁(y)^h₂(y) f(x, y) dx dy.","distractors":["D = {(x, y): a ≤ x ≤ b, g₁(x) ≤ y ≤ g₂(x)}; this vertical-slice form is called type II.","A type II region must be a disk centered at the origin.","A type II region allows each horizontal line to intersect infinitely many disjoint x intervals without splitting the region."],"explanation":"Type II regions are horizontally simple: x runs between left and right boundaries determined by y.","hint":"Use horizontal slices, from left to right, at each fixed y."}],"calculus-chapter-16-review-3-concept-check-1":[{"label":"a","selectionPrompt":"What is the definition of ∫_C f ds along a smooth curve?","answer":"The limit of sums Σ f(Pᵢ*) Δsᵢ as the arc-length partition mesh tends to 0, where Pᵢ* lies on the ith subarc and Δsᵢ is its length.","distractors":["The limit of Σ f(Pᵢ*) Δxᵢ for every curve, so vertical sections always contribute zero.","The sum of f values at all points without length weights.","The limit of sums of normal vectors over a two-dimensional surface."],"explanation":"This scalar line integral weights function values by small arc lengths, rather than coordinate increments or surface areas.","hint":"Break the curve into short arcs and attach a length weight to each sampled function value."}],"calculus-chapter-16-review-12-concept-check-1":[{"label":"a","selectionPrompt":"How is the surface integral of a scalar function defined?","answer":"∬_S f dS is the limit of sums Σ f(Pᵢ*) ΔSᵢ over small surface patches, as their maximum diameter tends to 0.","distractors":["∬_S f dS is the limit of sums weighted only by patch perimeter, not patch area.","∬_S f dS is the integral of f only around the boundary curve.","∬_S f dS is the triple integral over the volume inside S, for every surface."],"explanation":"A scalar surface integral accumulates values over area patches of the surface itself.","hint":"Choose the weight appropriate to a two-dimensional surface, rather than its boundary or interior volume."}],"physics-chapter-03-questions-1":[{"label":"","selectionPrompt":"Can the sum of two vector magnitudes equal the magnitude of their vector sum? If so, when?","answer":"Yes: when the nonzero vectors point in the same direction; equality also holds if either vector is zero.","distractors":["Yes: only when the two nonzero vectors point in opposite directions.","Yes: only when the two nonzero vectors are perpendicular.","No: the magnitude of the vector sum is always strictly smaller."],"explanation":"The triangle inequality gives |a + b| ≤ |a| + |b|. Equality holds for vectors with the same direction, including the zero-vector special case.","hint":"Compare the straight-line resultant with the two sides of a vector triangle."}],"physics-chapter-03-questions-4":[{"label":"","selectionPrompt":"Does commutativity of vector addition mean vector subtraction is also commutative?","answer":"No in general: a − b = −(b − a), and the two differences are equal only if a = b.","distractors":["Yes: a − b = b − a for every pair of vectors.","Yes, but only when the two vectors are perpendicular.","No: even when a = b, the two differences point in opposite nonzero directions."],"explanation":"Reversing subtraction negates the result. Both orders give the same vector only when both differences are zero.","hint":"Try reversing the order of subtracting two unequal vectors."}],"physics-chapter-04-questions-3":[{"label":"","selectionPrompt":"Why can launching an artillery shell above 45° increase its range in the situation described?","answer":"Air density decreases with altitude, so a higher trajectory can encounter less drag.","distractors":["Air density increases with altitude, so a higher trajectory encounters less drag.","Air density stays constant, and 45° is never the maximum-range angle even without drag.","Gravity reverses direction at high altitude and pushes the shell forward."],"explanation":"The ideal 45° maximum assumes no air resistance and equal launch and landing heights. Passing through thinner upper air can reduce drag enough to improve range.","hint":"The familiar 45° result assumes an ideal environment. Consider what changes higher above the ground."}],"physics-chapter-04-questions-13":[{"label":"a","selectionPrompt":"Can an object accelerate while traveling at constant speed?","answer":"Yes: its velocity can change direction while its speed stays constant.","distractors":["No: constant speed requires the entire velocity vector to stay constant.","Yes: constant speed means the object has a nonzero tangential acceleration.","Only if its mass changes during the motion."],"explanation":"Acceleration is the rate of change of velocity, including changes in direction. Uniform circular motion is one example.","hint":"Velocity contains more information than speed."},{"label":"b","selectionPrompt":"Can an object round a curve with zero acceleration?","answer":"No: moving around a curve changes the direction of velocity, which requires acceleration.","distractors":["Yes: zero acceleration is possible whenever the speed is constant.","Yes: every curved path has zero acceleration at its midpoint.","Yes: if the object has enough mass, no acceleration is needed."],"explanation":"A nonzero velocity tangent to a curved path changes direction. Its curvature gives a normal acceleration v²/R.","hint":"Ask whether the velocity direction can stay fixed on a curved path."},{"label":"c","selectionPrompt":"Can an object round a curve with a constant acceleration magnitude?","answer":"Yes: uniform circular motion has a constant acceleration magnitude v²/R even though the direction changes.","distractors":["No: acceleration magnitude must change whenever its direction changes.","Yes: but the acceleration must be zero everywhere.","Yes: only if the velocity vector is constant."],"explanation":"With constant speed and radius, v²/R is constant. The inward acceleration direction rotates as the object moves.","hint":"Distinguish the magnitude of a vector from its direction."}],"physics-chapter-04-questions-14":[{"label":"a","selectionPrompt":"After you toss an egg directly upward in a car traveling straight at constant speed, where does it tend to land? Neglect air resistance.","answer":"Back in your hands: the egg retains the car’s horizontal velocity.","distractors":["Behind you: the accelerating car moves ahead of the egg.","In front of you: the egg keeps moving faster horizontally than the slowing car.","It stops moving horizontally at release and falls vertically relative to the ground."],"explanation":"With negligible air resistance, the egg and the car have the same constant horizontal velocity.","hint":"Compare the car’s horizontal motion after release with the egg’s horizontal motion."},{"label":"b","selectionPrompt":"After you toss an egg directly upward in a car traveling straight and increasing in speed, where does it tend to land? Neglect air resistance.","answer":"Behind you: the accelerating car moves ahead of the egg.","distractors":["Back in your hands: the egg retains the car’s horizontal velocity.","In front of you: the egg keeps moving faster horizontally than the slowing car.","It stops moving horizontally at release and falls vertically relative to the ground."],"explanation":"The egg keeps its release-time horizontal velocity while the car speeds up.","hint":"Compare the car’s horizontal motion after release with the egg’s horizontal motion."},{"label":"c","selectionPrompt":"After you toss an egg directly upward in a car traveling straight and decreasing in speed, where does it tend to land? Neglect air resistance.","answer":"In front of you: the egg keeps moving faster horizontally than the slowing car.","distractors":["Back in your hands: the egg retains the car’s horizontal velocity.","Behind you: the accelerating car moves ahead of the egg.","It stops moving horizontally at release and falls vertically relative to the ground."],"explanation":"The egg retains its initial horizontal velocity while the car slows down.","hint":"Compare the car’s horizontal motion after release with the egg’s horizontal motion."}],"physics-chapter-04-questions-16":[{"label":"a","selectionPrompt":"You follow a pickup truck at the same speed when a crate falls from its bed. If you neither brake nor swerve, will your car hit it before it reaches the road? Neglect air resistance.","answer":"No: the crate keeps its initial horizontal speed, so the following car does not close the horizontal gap during the fall.","distractors":["Yes: the crate loses all horizontal velocity as soon as it leaves the truck.","Yes: gravity accelerates the crate backward toward the following car.","Yes: a falling object always moves more slowly horizontally than a vehicle."],"explanation":"During ideal projectile motion there is no horizontal acceleration. The crate and following car therefore maintain their horizontal separation until road contact.","hint":"Separate the horizontal motion from the downward fall."},{"label":"b","selectionPrompt":"During the crate’s fall from a truck moving at constant speed, how does its horizontal speed compare with the truck’s? Neglect air resistance.","answer":"The same: both retain the horizontal speed they had at release.","distractors":["Less: gravity slows the crate’s horizontal motion.","Greater: gravity also accelerates the crate forward.","Zero: all its motion becomes vertical at release."],"explanation":"Gravity acts vertically, so the crate’s horizontal velocity stays constant.","hint":"Which component of velocity does gravity change?"}],"physics-chapter-04-questions-17":[{"label":"","selectionPrompt":"At what point along an ideal projectile’s path is its speed smallest?","answer":"At the highest point, where the vertical velocity is zero and only the horizontal component remains.","distractors":["At release, because gravity has not yet acted on it.","Just before landing, because gravitational acceleration slows all falling objects.","At every point equally, because projectile velocity is constant."],"explanation":"Without air resistance, the horizontal speed is constant. The total speed √(vx² + vy²) is smallest when vy = 0.","hint":"Think about the two velocity components at the top of the path."}],"physics-chapter-04-questions-18":[{"label":"","selectionPrompt":"For a shot put launched above its landing level, which launch angle produces maximum range in the ideal no-drag model?","answer":"Less than 45°: the extra launch height already provides additional flight time.","distractors":["Exactly 45°: launch height never affects the maximizing angle.","Greater than 45°: a higher launch point always requires more vertical velocity.","Exactly 90°: the longest flight time always gives the longest horizontal range."],"explanation":"When the release point is above the landing level, the optimum angle is below 45°. More of the launch speed can be assigned to horizontal motion.","hint":"The equal-height 45° result changes when the projectile begins above the landing level."}],"physics-chapter-05-questions-11":[{"label":"a","selectionPrompt":"A block remains on a floor as an applied downward vertical force is increased. What happens to the normal-force magnitude?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Vertical equilibrium requires N = mg + F for a downward applied force.","hint":"Write the vertical force balance while the block stays on the floor."},{"label":"b","selectionPrompt":"As an applied upward vertical force on a block is increased from zero, what happens to the floor’s normal force?","answer":"It decreases to zero at F = mg; for larger upward force the block leaves the floor and the normal force stays zero.","distractors":["It increases continuously because the floor must resist the upward force.","It remains equal to mg for every applied upward force.","It becomes negative once F exceeds mg while the floor continues pulling downward."],"explanation":"While contact remains, N = mg − F. The floor can push but cannot pull the block; contact is lost when the required normal force reaches zero.","hint":"The contact force must be nonnegative. Consider the point where the upward force balances weight."}],"physics-chapter-06-questions-4":[{"label":"a","selectionPrompt":"A stationary block is subjected separately to horizontal forces F1 = 12 N, F2 = 8 N, and F3 = 4 N. Rank the actual static-friction magnitudes, greatest first.","answer":"f1 > f2 > f3: static friction balances the applied force in each stationary trial.","distractors":["f1 = f2 = f3: actual static friction is always its maximum value.","f3 > f2 > f1: a smaller applied force creates more friction.","f1 = f2 = f3 = 0: static friction vanishes whenever the block is at rest."],"explanation":"Because the block remains stationary, each horizontal applied force is balanced by an equal opposing static-friction force.","hint":"Use the condition that horizontal acceleration is zero in each trial."},{"label":"b","selectionPrompt":"For those three trials on the same stationary block and countertop, rank the maximum available static friction.","answer":"All three are equal: μsN is unchanged by these horizontal applied forces.","distractors":["Trial 1 > trial 2 > trial 3: the maximum friction equals the applied force.","Trial 3 > trial 2 > trial 1: weaker applied forces raise the maximum friction.","All three maxima are zero because the block is not sliding."],"explanation":"The limiting value μsN depends on the surfaces and normal force. Those remain unchanged; the actual friction can vary below that limit.","hint":"Distinguish actual static friction from its limiting value."}],"physics-chapter-06-questions-5":[{"label":"a","selectionPrompt":"You press a crate horizontally against a wall hard enough to keep it from sliding down. What direction does the wall’s static-friction force on the crate have?","answer":"Upward, opposing the crate’s tendency to slide downward.","distractors":["Downward, in the same direction as gravity.","Horizontally into the wall, in the direction of your push.","Horizontally away from the wall, normal to its surface."],"explanation":"The crate tends to slip down under gravity. Static friction acts upward along the wall and balances its weight.","hint":"Friction acts along the contact surface, opposing the impending relative motion."},{"label":"b","selectionPrompt":"What direction does the wall’s normal force on the supported crate have?","answer":"Horizontally away from the wall, perpendicular to its surface.","distractors":["Upward along the wall.","Downward along the wall.","Horizontally into the wall, in the direction of your push."],"explanation":"A normal contact force is perpendicular to the wall and pushes the crate away from it.","hint":"The word normal refers to a direction relative to the surface."},{"label":"c","selectionPrompt":"If you increase your horizontal push while the crate stays at rest against the wall, what happens to the actual static-friction magnitude?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"Static friction continues to balance mg; increasing the horizontal push increases the available maximum, not the friction needed to support the unchanged weight.","hint":"Compare the vertical forces before and after increasing the horizontal push."},{"label":"d","selectionPrompt":"If you increase your horizontal push on a crate held at rest against a wall, what happens to the wall’s normal-force magnitude?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The normal force balances the horizontal push, so a larger push produces a larger normal force.","hint":"Apply the horizontal equilibrium condition."},{"label":"e","selectionPrompt":"If you increase your horizontal push on a crate held at rest against a wall, what happens to its maximum available static friction?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The maximum value is μsN. A larger push raises N while μs stays the same.","hint":"Identify the quantities that set the limiting static-friction force."}],"physics-chapter-06-questions-13":[{"label":"a","selectionPrompt":"A box is on a ramp whose angle is increased from zero, before the box slips. What happens to the weight component along the ramp?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The downslope component mg sin θ increases as the ramp is raised from horizontal.","hint":"Resolve gravity into components parallel and perpendicular to the ramp; actual friction need not equal maximum friction."},{"label":"b","selectionPrompt":"A box is on a ramp whose angle is increased from zero, before the box slips. What happens to the actual static-friction magnitude?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Before slipping, static friction balances mg sin θ, which increases with the ramp angle.","hint":"Resolve gravity into components parallel and perpendicular to the ramp; actual friction need not equal maximum friction."},{"label":"c","selectionPrompt":"A box is on a ramp whose angle is increased from zero, before the box slips. What happens to the weight component perpendicular to the ramp?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The perpendicular component mg cos θ decreases as θ increases.","hint":"Resolve gravity into components parallel and perpendicular to the ramp; actual friction need not equal maximum friction."},{"label":"d","selectionPrompt":"A box is on a ramp whose angle is increased from zero, before the box slips. What happens to the normal-force magnitude?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"There is no acceleration normal to the ramp, so N = mg cos θ decreases.","hint":"Resolve gravity into components parallel and perpendicular to the ramp; actual friction need not equal maximum friction."},{"label":"e","selectionPrompt":"A box is on a ramp whose angle is increased from zero, before the box slips. What happens to the maximum available static friction?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The maximum μsN = μs mg cos θ decreases as the ramp angle grows.","hint":"Resolve gravity into components parallel and perpendicular to the ramp; actual friction need not equal maximum friction."}],"physics-chapter-11-questions-11":[{"label":"a","selectionPrompt":"A cannonball and a marble, modeled as uniform solid spheres, roll without slipping from rest down the same incline. How do their times to the bottom compare?","answer":"The same: their acceleration depends on I/(mR²), which is the same for both solid spheres.","distractors":["The cannonball arrives first because a greater mass always produces greater rolling acceleration.","The marble arrives first because a smaller radius always produces greater rolling acceleration.","Neither reaches the bottom because rolling consumes all the gravitational energy."],"explanation":"For a solid sphere I = (2/5)mR², so a = g sin θ/(1 + 2/5), independent of mass and radius.","hint":"Use the dimensionless rotational-inertia ratio rather than mass alone."},{"label":"b","selectionPrompt":"The cannonball is more massive than the marble. Both are uniform solid spheres rolling without slipping from the same height. How do their translational kinetic energies at the bottom compare?","answer":"The cannonball’s is greater: both have the same speed, but its mass is larger.","distractors":["They are equal: equal speeds always imply equal kinetic energies.","The marble’s is greater: a smaller sphere receives more gravitational energy.","Both are zero: all potential energy becomes rotational kinetic energy."],"explanation":"Both solid spheres have v² = (10/7)gh, but their translational energy is (1/2)mv². The more massive sphere therefore has more translational kinetic energy.","hint":"Compare speed first, then keep the mass in the kinetic-energy expression."}],"physics-chapter-11-questions-12":[{"label":"a","selectionPrompt":"A solid brass cylinder and solid wood cylinder have the same mass and radius but different lengths. Released together, they roll without slipping down an incline. Which arrives first?","answer":"They tie: both have I/(mR²) = 1/2, regardless of cylinder length.","distractors":["The brass cylinder arrives first because its density is greater.","The wood cylinder arrives first because its length is greater.","The brass cylinder arrives first because only its radius controls rolling acceleration."],"explanation":"For a uniform solid cylinder about its central axis, I = mR²/2. Equal shape ratios give equal rolling acceleration.","hint":"Find the rotational-inertia ratio for a uniform solid cylinder."},{"label":"b","selectionPrompt":"The wood cylinder is shortened; the brass cylinder is hollowed along its central axis to match the wood cylinder’s mass and length. Their outer radii remain equal. Which wins a rolling race?","answer":"The solid wood cylinder: removing the brass cylinder’s central material raises I/(mR²).","distractors":["The hollow brass cylinder: moving mass outward reduces its rotational inertia per unit mass.","They tie: equal mass and outer radius guarantee equal inertia for any mass distribution.","The hollow brass cylinder: density alone determines rolling acceleration."],"explanation":"An annular cylinder has I/(mR²) = (1 + Rin²/R²)/2, greater than 1/2 for a solid cylinder. Its greater ratio lowers its rolling acceleration.","hint":"Consider where the remaining brass mass lies relative to the rotation axis."}],"physics-chapter-12-questions-4":[{"label":"a","selectionPrompt":"A ladder rests against a frictionless wall and does not slip at the ground. After its base is moved closer to the wall and it is again at rest, what happens to the ground’s normal-force magnitude?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"The frictionless wall supplies only a horizontal force, so vertical force balance keeps the ground normal force equal to the ladder’s weight.","hint":"Use vertical force balance, horizontal force balance, and torque balance separately."},{"label":"b","selectionPrompt":"A ladder rests against a frictionless wall and does not slip at the ground. After its base is moved closer to the wall and it is again at rest, what happens to the wall’s force magnitude?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Moving the base closer makes the ladder steeper. Torque balance gives a wall force proportional to the horizontal-to-vertical lever-arm ratio, which decreases.","hint":"Use vertical force balance, horizontal force balance, and torque balance separately."},{"label":"c","selectionPrompt":"A ladder rests against a frictionless wall and does not slip at the ground. After its base is moved closer to the wall and it is again at rest, what happens to the ground’s actual static-friction magnitude?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Horizontal equilibrium makes the ground friction equal to the wall force, which decreases for a steeper ladder.","hint":"Use vertical force balance, horizontal force balance, and torque balance separately."},{"label":"d","selectionPrompt":"A ladder rests against a frictionless wall and does not slip at the ground. After its base is moved closer to the wall and it is again at rest, what happens to the ground’s maximum available static friction?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"The coefficient of static friction and ground normal force remain unchanged, so μsN stays fixed.","hint":"Use vertical force balance, horizontal force balance, and torque balance separately."}],"physics-chapter-14-questions-1":[{"label":"a","selectionPrompt":"A fully submerged 3 kg lump is released in the stated fluid, whose displaced mass is 2 kg. What does it do?","answer":"Moves downward: its weight is greater than the buoyant force.","distractors":["Moves upward: every fully submerged object has a buoyant force greater than its weight.","Remains in place: full submersion guarantees neutral buoyancy.","Moves upward because its own mass determines the buoyant force."],"explanation":"Archimedes’ principle gives buoyancy equal to displaced-fluid weight. Initially that is 2g, below the lump’s 3g weight; a less dense fluid makes buoyancy even smaller.","hint":"Compare the lump’s weight with the weight of the fluid it displaces."},{"label":"b","selectionPrompt":"A fully submerged 3 kg lump is released in a less dense fluid. What does it do?","answer":"Moves downward: its weight is greater than the buoyant force.","distractors":["Moves upward: every fully submerged object has a buoyant force greater than its weight.","Remains in place: full submersion guarantees neutral buoyancy.","Moves upward because its own mass determines the buoyant force."],"explanation":"Archimedes’ principle gives buoyancy equal to displaced-fluid weight. Initially that is 2g, below the lump’s 3g weight; a less dense fluid makes buoyancy even smaller.","hint":"Compare the lump’s weight with the weight of the fluid it displaces."}],"physics-chapter-14-questions-3":[{"label":"a","selectionPrompt":"A dense anchor is dropped from a floating boat into a swimming pool, where it sinks. What happens to the pool water level?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"On board, the anchor makes the boat displace water equal to its weight. Submerged, the anchor displaces only its own volume; because it is denser than water, that volume is smaller.","hint":"Compare weight-based displacement while on board with volume-based displacement after sinking."},{"label":"b","selectionPrompt":"An anchor is removed from a floating boat and thrown onto the surrounding ground. What happens to the pool water level?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The boat now displaces less water and the anchor on land displaces none of the pool water.","hint":"Which objects displace pool water before and after the anchor is removed?"},{"label":"c","selectionPrompt":"A cork is dropped from a floating boat into the pool, where the cork floats. What happens to the pool water level?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"Whether supported by the boat or floating independently, the cork requires displaced water with the same weight as the cork.","hint":"For an object that floats, compare its weight with displaced-fluid weight."}],"physics-chapter-19-questions-9":[{"label":"","selectionPrompt":"An ideal diatomic gas loses the same amount of heat in a constant-volume or constant-pressure process. In which case is the decrease in internal energy greater?","answer":"At constant volume: all the lost heat reduces internal energy; at constant pressure, compression does work on the gas.","distractors":["At constant pressure: compression removes extra internal energy from the gas.","The decreases are equal because internal energy change always equals heat transfer.","Neither decreases: heat transfer cannot change an ideal gas’s internal energy."],"explanation":"At constant volume ΔU = Q. For constant-pressure cooling, ΔU = (Cv/Cp)Q with Cv/Cp < 1, so the magnitude of the internal-energy decrease is smaller.","hint":"Include boundary work in the first law; constant volume and constant pressure do not have the same work term."}],"physics-chapter-19-questions-10":[{"label":"a","selectionPrompt":"For a fixed amount of ideal gas undergoing an isothermal expansion, what happens to temperature?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"Isothermal means constant temperature by definition.","hint":"Identify the constraint on heat, temperature, volume, or pressure before applying the gas law or first law."},{"label":"b","selectionPrompt":"For a fixed amount of ideal gas undergoing an expansion at constant pressure, what happens to temperature?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"For a fixed amount of ideal gas, PV = nRT. At fixed P, increasing V requires increasing T.","hint":"Identify the constraint on heat, temperature, volume, or pressure before applying the gas law or first law."},{"label":"c","selectionPrompt":"For a fixed amount of ideal gas undergoing an adiabatic expansion against a resisting pressure, what happens to temperature?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"With Q = 0 and positive work done by the gas, ΔU is negative. Ideal-gas internal energy decreases with temperature.","hint":"Identify the constraint on heat, temperature, volume, or pressure before applying the gas law or first law."},{"label":"d","selectionPrompt":"For a fixed amount of ideal gas undergoing an increase in pressure at constant volume, what happens to temperature?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"At fixed V and n, PV = nRT makes temperature proportional to pressure.","hint":"Identify the constraint on heat, temperature, volume, or pressure before applying the gas law or first law."}],"physics-chapter-21-questions-6":[{"label":"a","selectionPrompt":"A positive ball is near a neutral conductor that is grounded. If the ball is removed first and the ground connection is removed afterward, what is the conductor’s final net charge?","answer":"Neutral: with the ball absent and grounding still present, the excess induced charge flows back to Earth.","distractors":["Negative: grounding permanently fixes all induced electrons on the conductor.","Positive: removing a positive ball transfers its positive charge to the conductor.","The same positive charge as the ball, because charge induction copies its sign."],"explanation":"The nearby positive ball attracts electrons from ground. Removing the ball while grounding remains lets those excess electrons leave, restoring neutrality.","hint":"The order matters because charge can still flow while the conductor is connected to Earth."},{"label":"b","selectionPrompt":"In the same induction experiment, the ground connection is removed first, then the positive ball is taken away. What is the conductor’s final net charge?","answer":"Negative: excess electrons remain trapped on the now-isolated conductor.","distractors":["Neutral: removing the ball automatically removes all induced net charge.","Positive: the conductor acquires the same sign as the nearby ball.","Zero until touched: an isolated conductor cannot retain net charge."],"explanation":"Grounding near a positive ball supplies extra electrons. Disconnecting ground first traps them; removing the ball then changes their distribution but not the net charge.","hint":"After disconnection, distinguish redistribution of charge from transfer of charge."}],"physics-chapter-25-questions-5":[{"label":"a","selectionPrompt":"C1 is connected to a battery. C2 is added in parallel while the battery stays connected. What happens to the potential difference across C1?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"With C1 still directly across the battery, its voltage remains the battery voltage.","hint":"For a parallel connection, identify which voltage stays fixed and how capacitances combine."},{"label":"b","selectionPrompt":"C1 is connected to a battery. C2 is added in parallel while the battery stays connected. What happens to the charge on C1?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"q1 = C1V is unchanged because neither C1 nor its voltage changes.","hint":"For a parallel connection, identify which voltage stays fixed and how capacitances combine."},{"label":"c","selectionPrompt":"C1 is connected to a battery. C2 is added in parallel while the battery stays connected. What happens to the equivalent capacitance compared with C1 alone?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Parallel capacitances add: C12 = C1 + C2.","hint":"For a parallel connection, identify which voltage stays fixed and how capacitances combine."},{"label":"d","selectionPrompt":"C1 is connected to a battery. C2 is added in parallel while the battery stays connected. What happens to the total stored charge compared with C1 alone?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"At fixed battery voltage, qtotal = (C1 + C2)V exceeds C1V.","hint":"For a parallel connection, identify which voltage stays fixed and how capacitances combine."}],"physics-chapter-25-questions-9":[{"label":"a","selectionPrompt":"A parallel-plate capacitor remains connected to a battery while its plate separation is decreased, with plate area and dielectric unchanged. What happens to its capacitance?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"For parallel plates, C = εA/d; reducing separation d raises C.","hint":"The battery keeps voltage fixed; use C = εA/d and E = V/d."},{"label":"b","selectionPrompt":"A parallel-plate capacitor remains connected to a battery while its plate separation is decreased, with plate area and dielectric unchanged. What happens to its potential difference?","answer":"Remains the same","distractors":["Increases","Decreases","Cannot be determined from the stated conditions"],"explanation":"The connected battery holds the plate voltage fixed.","hint":"The battery keeps voltage fixed; use C = εA/d and E = V/d."},{"label":"c","selectionPrompt":"A parallel-plate capacitor remains connected to a battery while its plate separation is decreased, with plate area and dielectric unchanged. What happens to its stored charge?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"q = CV increases because C increases and battery voltage stays fixed.","hint":"The battery keeps voltage fixed; use C = εA/d and E = V/d."},{"label":"d","selectionPrompt":"A parallel-plate capacitor remains connected to a battery while its plate separation is decreased, with plate area and dielectric unchanged. What happens to its stored energy?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"U = CV²/2 increases at fixed V as C increases.","hint":"The battery keeps voltage fixed; use C = εA/d and E = V/d."},{"label":"e","selectionPrompt":"A parallel-plate capacitor remains connected to a battery while its plate separation is decreased, with plate area and dielectric unchanged. What happens to its electric-field magnitude?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Ignoring edge effects, E = V/d increases as d decreases at fixed V.","hint":"The battery keeps voltage fixed; use C = εA/d and E = V/d."},{"label":"f","selectionPrompt":"A parallel-plate capacitor remains connected to a battery while its plate separation is decreased, with plate area and dielectric unchanged. What happens to its electric-field energy density?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"u = εE²/2 grows as the electric-field magnitude increases.","hint":"The battery keeps voltage fixed; use C = εA/d and E = V/d."}],"physics-chapter-27-questions-7":[{"label":"a","selectionPrompt":"R1 is wired to a fixed-voltage battery, then R2 is added in series. What happens to the potential difference across R1?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The current becomes V/(R1 + R2); multiplying by R1 gives a smaller voltage than the original battery voltage.","hint":"Find the new series resistance before applying Ohm’s law."},{"label":"b","selectionPrompt":"R1 is wired to a fixed-voltage battery, then R2 is added in series. What happens to the current through R1?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Adding a positive series resistance increases total resistance at the same battery voltage.","hint":"Find the new series resistance before applying Ohm’s law."},{"label":"c","selectionPrompt":"R1 is wired to a fixed-voltage battery, then R2 is added in series. What happens to the equivalent resistance compared with R1 alone?","answer":"Increases","distractors":["Decreases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Series resistances add: R12 = R1 + R2.","hint":"Find the new series resistance before applying Ohm’s law."}],"physics-chapter-27-questions-9":[{"label":"a","selectionPrompt":"For two resistors and their equivalent resistance, in which arrangement are the potential differences across all three equal?","answer":"Parallel: each branch spans the same two terminals.","distractors":["Series: equal current always requires equal voltage across all resistances.","Both series and parallel, regardless of resistor values.","Neither: an equivalent resistor cannot have the same voltage as a real resistor."],"explanation":"Parallel branches share both endpoints, so each resistor and the equivalent combination have the terminal voltage.","hint":"Compare the endpoint connections of a series circuit and a parallel circuit."},{"label":"b","selectionPrompt":"For two resistors and their equivalent resistance, in which arrangement are the currents through all three equal?","answer":"Series: there is one current path through both resistors.","distractors":["Parallel: branch currents always equal the total current.","Both series and parallel, regardless of resistor values.","Neither: an equivalent resistor cannot carry the same current as a real resistor."],"explanation":"In series, no charge can accumulate between the resistors in steady state, so the same current passes through each and through the equivalent combination.","hint":"Ask whether the current has a junction where it can split."}],"physics-chapter-34-questions-5":[{"label":"","selectionPrompt":"A vehicle side-view mirror carries the warning “Objects in mirror are closer than they appear.” Is the mirror flat, convex, or concave?","answer":"Convex: its reduced upright images can make objects appear farther away.","distractors":["Flat: its images are smaller than the objects and therefore always seem farther away.","Concave: it always produces reduced upright images of distant objects.","Neither flat nor curved: the warning is caused only by the mirror’s tint."],"explanation":"A convex mirror forms upright reduced virtual images over a wide field of view. Their reduced size can distort perceived distance.","hint":"Which mirror gives a wide field of view with upright images smaller than the objects?"}],"physics-chapter-35-questions-1":[{"label":"a","selectionPrompt":"In a two-slit interference experiment with other conditions fixed, how does fringe spacing change if the slit separation is increased?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Fringe spacing Δy = λL/d is inversely proportional to slit separation d.","hint":"Use the dependence of fringe spacing on wavelength, screen distance, and slit separation."},{"label":"b","selectionPrompt":"In a two-slit interference experiment with other conditions fixed, how does fringe spacing change if the light is changed from red to blue?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Blue has a shorter wavelength, and fringe spacing is proportional to wavelength.","hint":"Use the dependence of fringe spacing on wavelength, screen distance, and slit separation."},{"label":"c","selectionPrompt":"In a two-slit interference experiment with other conditions fixed, how does fringe spacing change if the whole apparatus is submerged in a transparent liquid such as cooking sherry?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"The wavelength in the liquid is smaller than in air by the refractive index, reducing the fringe spacing.","hint":"Use the dependence of fringe spacing on wavelength, screen distance, and slit separation."},{"label":"d","selectionPrompt":"With white light illuminating two slits, which component’s peak is closer to the central maximum at a given side order?","answer":"Blue: its shorter wavelength places that order closer to the center.","distractors":["Red: its longer wavelength places that order closer to the center.","Both peak at exactly the same position in every order.","Neither appears outside the central maximum."],"explanation":"For the same order m, the fringe position is approximately mλL/d. Smaller λ gives a smaller distance from the center.","hint":"Compare wavelengths while keeping the fringe order fixed."}],"physics-chapter-36-questions-6":[{"label":"a","selectionPrompt":"In a single-slit diffraction experiment, the light frequency is changed from f to 1.3f with the same medium and slit. What happens to the pattern width?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"A greater frequency gives a shorter wavelength λ = v/f. Diffraction angles shrink with wavelength.","hint":"Relate frequency to wavelength in the same medium, then wavelength to diffraction angle."},{"label":"b","selectionPrompt":"In a single-slit diffraction experiment, the equipment is submerged in transparent corn syrup while the source frequency stays the same. What happens to the pattern width?","answer":"Decreases","distractors":["Increases","Remains the same","Cannot be determined from the stated conditions"],"explanation":"Light travels more slowly in the liquid while frequency remains fixed, shortening the wavelength and narrowing the diffraction pattern.","hint":"At a boundary the frequency stays fixed, while speed and wavelength change."}],"physics-chapter-38-questions-1":[{"label":"a","selectionPrompt":"Photon A has twice the energy of photon B. How do their momentum magnitudes compare?","answer":"A has greater momentum: pA = 2pB because p = E/c.","distractors":["Their momenta are equal because all photons have the same speed.","A has smaller momentum: pA = pB/2.","Both momenta are zero because photons have zero rest mass."],"explanation":"A photon has momentum p = E/c, so doubling energy doubles momentum.","hint":"Photon momentum is linked to energy even though photon rest mass is zero."},{"label":"b","selectionPrompt":"Photon A has twice the energy of photon B. How do their wavelengths compare?","answer":"A has a shorter wavelength: λA = λB/2 because E = hc/λ.","distractors":["Their wavelengths are equal because both travel at c.","A has a longer wavelength: λA = 2λB.","A has a longer wavelength: λA = 4λB."],"explanation":"Photon energy is inversely proportional to wavelength, so twice the energy means half the wavelength.","hint":"Use the inverse relationship between photon energy and wavelength."}],"physics-chapter-38-questions-12":[{"label":"","selectionPrompt":"An electron and a proton have the same kinetic energy. Which has the greater de Broglie wavelength?","answer":"The electron: its smaller mass gives smaller momentum at equal kinetic energy, so h/p is larger.","distractors":["The proton: greater mass always means greater de Broglie wavelength.","They are equal: equal kinetic energy always means equal momentum.","Neither has a wavelength because both particles have nonzero rest mass."],"explanation":"In the nonrelativistic regime p = √(2mK). At fixed K the smaller mass gives smaller p and therefore larger λ = h/p.","hint":"Express momentum in terms of mass and kinetic energy before comparing wavelengths."}],"physics-chapter-39-questions-2":[{"label":"","selectionPrompt":"Compare the ground-state energies of a proton and an electron trapped in the same one-dimensional infinite potential well.","answer":"The proton’s is smaller: at fixed well width, the ground-state energy is inversely proportional to mass.","distractors":["The proton’s is greater: a heavier particle must always have greater ground-state energy.","They are equal: well width alone determines the ground-state energy.","Both are zero because particles have no kinetic energy in their ground state."],"explanation":"For an infinite well, E1 = h²/(8mL²). The larger proton mass gives the smaller energy.","hint":"Check the mass dependence of the infinite-well energy levels."}],"physics-chapter-39-questions-5":[{"label":"","selectionPrompt":"A proton and an electron occupy the ground states of identical one-dimensional infinite potential wells. How do their probability densities at the centers compare?","answer":"They are equal: the normalized ground-state spatial wavefunction depends on well width, not particle mass.","distractors":["The proton’s is greater because its mass is greater.","The electron’s is greater because its ground-state energy is greater.","Both are zero because the center is a ground-state node."],"explanation":"The ground-state density is (2/L)sin²(πx/L). At the center it is 2/L for either mass; mass changes the energy but not this eigenfunction.","hint":"Separate the energy formula from the normalized position wavefunction."}],"organic-6-19":[{"label":"","selectionPrompt":"How does a transition state differ from a reaction intermediate?","answer":"A transition state is an energy maximum along a reaction step; an intermediate occupies a local energy minimum between steps.","distractors":["A transition state is an energy minimum; an intermediate is the energy maximum between reactants and products.","Both are stable products at the end of a reaction and occupy the same energy minimum.","An intermediate exists only in a concerted one-step reaction; a transition state occurs only after the reaction is complete."],"explanation":"On a reaction-energy diagram, peaks correspond to transition states and valleys between peaks correspond to intermediates. An intermediate has a finite lifetime; a transition state is not an isolable species.","hint":"Compare the peaks and valleys of a reaction-energy diagram."}],"organic-29-33":[{"label":"","selectionPrompt":"Which statement distinguishes digestion from metabolism?","answer":"Digestion breaks food into absorbable components; metabolism encompasses the chemical reactions of living cells, including synthesis and breakdown.","distractors":["Digestion builds large molecules inside cells; metabolism only breaks food down in the digestive tract.","Digestion is all chemical activity in cells; metabolism is exclusively the absorption of food into the bloodstream.","Digestion and metabolism both refer only to building proteins from amino acids."],"explanation":"Digestion prepares nutrients for absorption. Metabolism is the broader set of biochemical reactions by which cells transform matter and energy.","hint":"Distinguish preparation of food for absorption from the full set of cellular chemical reactions."}],"organic-29-34":[{"label":"","selectionPrompt":"How do anabolism and catabolism differ?","answer":"Anabolism builds complex molecules and generally requires energy; catabolism breaks molecules down and generally releases usable energy.","distractors":["Anabolism breaks molecules down and releases energy; catabolism builds complex molecules and requires energy.","Both exclusively break large molecules into smaller molecules and always consume energy.","Both exclusively build large molecules from smaller molecules and always release energy."],"explanation":"Biosynthetic pathways are anabolic. Degradative pathways are catabolic and often transfer released energy into ATP or reduced electron carriers.","hint":"Associate one term with biosynthesis and the other with degradation."}],"organic-2-46":[{"label":"","selectionPrompt":"Given the conjugate-acid pKa values 9.25 for NH4+ and 10.66 for CH3NH3+, which base is stronger?","answer":"Methylamine is stronger: its conjugate acid has the higher pKa and is therefore the weaker acid.","distractors":["Ammonia is stronger: its conjugate acid has the lower pKa and is therefore the weaker acid.","Both bases are equally strong because both molecules contain nitrogen.","Neither conjugate-acid pKa value can be used to compare the strengths of these bases."],"explanation":"For conjugate acid–base pairs in the same medium, higher conjugate-acid pKa means a weaker acid and a stronger conjugate base. Since 10.66 > 9.25, methylamine is the stronger base.","hint":"Compare the strengths of the conjugate acids before comparing their bases."}],"organic-2-47":[{"label":"","selectionPrompt":"With tert-butyl alcohol pKa approximately 18 and water pKa approximately 15.7, can tert-butoxide persist without substantial protonation in water?","answer":"No. Tert-butoxide reacts significantly with water to give tert-butyl alcohol and hydroxide, because the products contain the weaker acid.","distractors":["Yes. Water is too weak an acid to protonate tert-butoxide, because its pKa is lower than that of tert-butyl alcohol.","Yes. Dissolving the potassium salt prevents all acid–base reactions with water.","No. Tert-butoxide reacts with water by losing a proton and forming a stronger acid."],"explanation":"For tert-butoxide + H2O ⇌ tert-butyl alcohol + OH−, K is approximately 10^(18 − 15.7), well above 1. The equilibrium favors tert-butyl alcohol and hydroxide.","hint":"Write the proton-transfer reaction and compare the pKa values of the acid on each side."}],"organic-2-1":[{"label":"a","selectionPrompt":"Which is more electronegative: Li or H?","answer":"H","distractors":["Li","Both have equal electronegativity"],"explanation":"Hydrogen has a higher electronegativity than lithium: it attracts shared bonding electrons more strongly.","hint":"Compare the tendency to attract shared bonding electrons."},{"label":"b","selectionPrompt":"Which is more electronegative: B or Br?","answer":"Br","distractors":["B","Both have equal electronegativity"],"explanation":"Bromine has a higher electronegativity than boron.","hint":"Compare the tendency to attract shared bonding electrons."},{"label":"c","selectionPrompt":"Which is more electronegative: Cl or I?","answer":"Cl","distractors":["I","Both have equal electronegativity"],"explanation":"Electronegativity decreases down the halogen group, so chlorine is more electronegative than iodine.","hint":"Use the trend down the halogen group."},{"label":"d","selectionPrompt":"Which is more electronegative: C or H?","answer":"C","distractors":["H","Both have equal electronegativity"],"explanation":"Carbon is slightly more electronegative than hydrogen, so C–H bonds are weakly polarized toward carbon.","hint":"Compare carbon and hydrogen on the electronegativity scale."}]};
